'Custom_SMS_Guide_Title' => 'Come configurare',
'Custom_SMS_Guide_Intro' => 'È possibile collegare qualsiasi provider SMS dotato di API HTTP. Apra la documentazione API del provider, copi endpoint, metodo e nomi dei campi, quindi li mappi qui sotto utilizzando i segnaposto.',
