'Custom_SMS_Guide_Method' => 'POST è il più comune. Scelga GET solo se il provider si aspetta tutto nell\'URL — in tal caso i campi del payload vengono inviati come parametri di query.',
'Custom_SMS_Guide_Content_Type' => '"json" invia il payload come corpo JSON (application/json). "form" lo invia come un classico modulo HTML (application/x-www-form-urlencoded). Verifichi quale dei due si aspetta il provider; con GET viene ignorato.',
'Custom_SMS_Guide_Sender' => 'Il Sender ID approvato o il numero di telefono di invio. Compila solo il segnaposto {sender} — per essere trasmesso deve essere usato nel payload, nelle intestazioni o nell\'URL.',
'Custom_SMS_Guide_Success_Keyword' => 'Facoltativa ma consigliata. Alcuni provider rispondono "200 OK" anche quando l\'invio non riesce. Inserisca una parola o un frammento che compare solo in una risposta positiva (ad es. success). Se la risposta non lo contiene, l\'SMS viene considerato non inviato.',
'Custom_SMS_Guide_Headers' => 'Intestazioni di autenticazione richieste dal provider, ad es. Authorization = Bearer YOUR_API_KEY, oppure Api-Key = YOUR_API_KEY. Non aggiunga Content-Type — viene impostato automaticamente.',
'Custom_SMS_Guide_Payload' => 'I campi del corpo della richiesta, con i nomi esatti indicati nella documentazione del provider. Usi i segnaposto come valori, ad es. to = {phone}, message = {message}, from = {sender}.',
