'Cr_Guide_T_Booking' => 'Prenotazione degli ordini',
'Cr_Guide_B_Booking' => '«Invia al corriere» compila il modulo a partire dalla vendita: destinatario, indirizzo, l\'importo ancora da pagare come contrassegno e il peso dei prodotti. I corrieri con un proprio elenco di città mostrano un selettore, e la scelta viene ricordata per quella città. Aggregatori, DHL, FedEx, UPS e Lalamove offrono «Confronta tariffe»: scelga un prezzo e «Prenota» lo acquista. È possibile prenotare più vendite insieme dall\'elenco vendite.',
'Cr_Guide_T_Cod' => 'Contrassegno',
'Cr_Guide_B_Cod' => 'Un pacco in contrassegno passa da «Non incassato» a «Incassato dal corriere» (alla consegna) a «Versato a Lei». I corrieri che comunicano i versamenti eseguono da soli l\'ultimo passaggio; per gli altri usi «Aggiorna contrassegno». Se in Impostazioni corrieri è stato scelto un conto, il versamento viene registrato come pagamento sulla vendita. Le spese del corriere possono essere salvate come spesa una volta concluso il pacco.',
'Cr_Guide_T_Returns' => 'Pacchi resi',
'Cr_Guide_B_Returns' => 'Per impostazione predefinita un pacco reso attende in Spedizioni con corriere, sotto «Resi da verificare». «Rimetti in giacenza» crea un reso di vendita per l\'intero ordine e rimette gli articoli in giacenza; «Ignora» non reintegra nulla, per pacchi danneggiati o smarriti. In alternativa, Impostazioni corrieri può reintegrare la giacenza automaticamente.',
'Cr_Guide_T_Customers' => 'Messaggi ai clienti e pagina di tracciamento',
'Cr_Guide_B_Customers' => 'Le notifiche ai clienti in Impostazioni corrieri inviano SMS, email o WhatsApp agli stati selezionati, una volta per pacco, con il Suo testo. La pagina di tracciamento del Suo negozio online consente ai clienti di seguire un pacco tramite il numero di tracciamento, oppure tramite numero d\'ordine e telefono. I clienti che restituiscono spesso i pacchi ricevono un badge di rischio reso al momento della prenotazione.',
'Cr_Guide_T_Labels' => 'Etichette',
'Cr_Guide_B_Labels' => '«Stampa etichetta» fornisce l\'etichetta del corriere quando questo ne emette una (un PDF, un link o un\'immagine), altrimenti un\'etichetta Stocky con il codice a barre di tracciamento e l\'importo da incassare. Per stampare, consenta i pop-up per questo sito. DHL, FedEx e UPS forniscono la loro etichetta una sola volta, alla prenotazione, e Stocky la conserva per le ristampe.',
'Cr_Guide_T_Faq' => 'Risoluzione dei problemi',
'Cr_Guide_Q_Test' => 'Il test di connessione non riesce',
'Cr_Guide_A_Test' => 'Le chiavi di test vanno con la Modalità test e le chiavi live con Live; sono diverse. Apra Log dei corrieri e legga la risposta del corriere per conoscere il motivo esatto.',
'Cr_Guide_Q_City' => 'Il corriere rifiuta la città o l\'indirizzo',
'Cr_Guide_A_City' => 'Scelga la città dall\'elenco città del corriere nel modulo di prenotazione; i corrieri accettano solo i propri nomi. I corrieri che lavorano con indirizzi postali richiedono anche provincia/stato, codice postale e codice paese di due lettere.',
'Cr_Guide_Q_Webhook' => 'Gli stati non cambiano da soli',
'Cr_Guide_A_Webhook' => 'Per i corrieri che inviano aggiornamenti, verifichi che l\'URL del webhook sia registrato presso il corriere: Log dei corrieri mostra ogni aggiornamento ricevuto, o il motivo per cui è stato rifiutato (ad esempio un secret errato). Gli altri corrieri vengono verificati secondo la pianificazione impostata in Impostazioni corrieri, e «Controlla stato ora» interroga subito il corriere.',
'Cr_Guide_Q_Stuck' => 'Una spedizione mostra un errore di verifica dello stato',
'Cr_Guide_A_Stuck' => 'Il corriere ha rifiutato le ultime verifiche; il motivo è indicato sulla spedizione e in Log dei corrieri. Dopo ripetuti errori una spedizione non viene più verificata automaticamente: risolva la causa, quindi usi «Controlla stato ora».',
'Cr_Guide_Q_Label' => 'Non si apre nulla quando si stampa un\'etichetta',
'Cr_Guide_A_Label' => 'Il browser ha bloccato il pop-up. Consenta i pop-up per questo sito e riprovi.',
'Cr_Guide_Q_Cod' => 'Un versamento del contrassegno non è stato registrato sulla vendita',
'Cr_Guide_A_Cod' => 'In Impostazioni corrieri, il contrassegno richiede l\'interruttore attivo e un conto selezionato. Senza un conto, i versamenti vengono solo contrassegnati come versati.',
