'Restrict_Master_Data_By_Warehouse' => 'Limita i dati anagrafici per magazzino',
'Restrict_Master_Data_By_Warehouse_Help' => 'Se attivo, un utente assegnato a magazzini specifici vede solo i prodotti, i clienti, i fornitori, le marche e le categorie collegati a quei magazzini. I record non ancora utilizzati da nessuna parte restano visibili, così quelli appena creati non vengono mai nascosti. Vendite, acquisti e resi sono sempre limitati e non dipendono da questo interruttore.',
'Restrict_Products_By_Warehouse' => 'Limita i prodotti per magazzino',
'Restrict_Products_By_Warehouse_Help' => 'Ogni prodotto ha un magazzino di appartenenza — la filiale per cui è stato creato. Se attivo, un utente assegnato a magazzini specifici vede, vende e modifica solo i prodotti il cui magazzino di appartenenza è uno dei suoi, più i prodotti che hanno giacenza effettiva in uno dei suoi magazzini (trasferita o acquistata). Gli utenti che possono accedere a tutti i magazzini vedono sempre tutto. Il negozio online segue la stessa regola: elenca solo i prodotti dei magazzini selezionati in Impostazioni negozio.',
'Virtual_Combo_Stock' => 'Giacenza virtuale dei combo',
'Virtual_Combo_Stock_Help' => 'Se attivo, un prodotto combo non ha una giacenza propria: la sua disponibilità è il numero di combo che i prodotti componenti possono ancora formare, e la vendita di un combo preleva la giacenza dai componenti. Se disattivo, i combo devono prima essere assemblati in giacenza con una rettifica.',
'Virtual_Combo_Stock_Warning' => 'Meglio sceglierlo prima di vendere combo. Dopo che dei combo sono stati venduti o resi, cambiare impostazione fa sì che le successive modifiche, eliminazioni e resi di quei documenti stornino la giacenza nel modo sbagliato.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Attivare la giacenza virtuale dei combo?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'I combo verranno venduti direttamente dai prodotti componenti e la loro giacenza propria non verrà più utilizzata.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Disattivare la giacenza virtuale dei combo?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'I combo torneranno alla propria giacenza, che dovrà essere assemblata dai componenti con una rettifica prima di poterli vendere.',
'Home_Warehouse' => 'Magazzino di appartenenza',
'Home_Warehouse_Hint' => 'La filiale a cui appartiene questo prodotto. Gli utenti limitati ad altri magazzini non lo vedranno, a meno che non vi venga trasferita della giacenza.',
'Home_Warehouse_Required' => 'Scelga il magazzino a cui appartiene questo prodotto.',
'Combo_products_required' => 'Aggiunga almeno un prodotto al combo.',
'Customer_Performance_Help' => 'Mostra un punteggio di rendimento e una valutazione nella pagina del cliente, basati sull\'affidabilità nei pagamenti, su quanto di recente ha acquistato e sul suo tasso di reso.',
'Product_Supplier' => 'Fornitore sui prodotti',
'Product_Supplier_Help' => 'Aggiunge un campo fornitore predefinito al modulo prodotto, lo mostra come colonna nell\'elenco prodotti e consente di filtrare i prodotti per fornitore per creare un elenco di riordino.',
'Default_Supplier_Hint' => 'Il fornitore da cui riordina abitualmente questo prodotto. Filtri l\'elenco prodotti per fornitore per vedere tutto ciò da ordinare presso di lui.',
