'Recon_Auto_Off' => 'Le registrazioni automatiche sono disattivate, quindi le nuove transazioni non vengono registrate in contabilità generale e risulteranno come registrazioni mancanti. Le attivi in Impostazioni → Attivazione funzionalità.',
