'Tg_Guide_Administrator' => 'amministratore',
'Tg_Guide_GetUpdates_Intro' => 'Per un gruppo o un canale, apra questo indirizzo in un browser inserendovi il Suo token, e lo aggiorni dopo aver pubblicato:',
'Tg_Guide_GetUpdates_Note' => 'Cerchi {chatId}. L\'ID di un gruppo o di un canale è negativo, ad es. {example} — lo copi per intero, segno meno compreso.',
'Tg_Guide_Step3_Title' => 'Collegalo qui',
'Tg_Guide_Step3_Body' => 'Nella scheda {settings} incolli il token del bot e il chat ID, scelga {allEvents} o solo quelli desiderati ({events}…), attivi {enable} e salvi. Poi prema {sendTest}.',
'Tg_Guide_State_Enabled' => 'abilitato',
'Tg_Guide_State_Saved_Off' => 'salvato, ma disattivato',
'Tg_Guide_State_Not_Configured' => 'non ancora configurato',
'Tg_Guide_Chat_Id' => 'chat {id}',
'Tg_Guide_How_Sent' => 'Come vengono inviati i messaggi',
'Tg_Guide_A_Title' => 'Subito — niente da installare',
'Tg_Guide_A_Body' => 'Una vendita, un acquisto, un pagamento o una spesa salvati in Stocky — al POS o nell\'area di amministrazione — vengono inviati a Telegram {rightAfter} il salvataggio, nella stessa richiesta. Nessuna voce cron, nessun queue worker, e il cassiere non aspetta mai Telegram: la vendita ha già ricevuto risposta quando il messaggio parte.',
'Tg_Guide_Right_After' => 'subito dopo',
'Tg_Guide_B_Title' => 'La voce cron — per i nuovi tentativi e gli eventi in background',
'Tg_Guide_B_Body' => 'Due tipi di messaggio attendono invece nella coda propria di Telegram: un invio non riuscito (Telegram momentaneamente irraggiungibile), che viene ritentato fino ad altre tre volte nei minuti successivi; e gli eventi generati al di fuori dell\'area di amministrazione — ordini importati da WooCommerce o Shopify, comandi artisan. Questa voce cron li invia, e nient\'altro:',
'Tg_Guide_B_Note' => 'Ogni minuto va bene: un\'esecuzione senza nulla in attesa termina subito. Su cPanel va inserita in {cronJobs} — usi il percorso completo di PHP 8.2+ se {php} è più vecchio. Su Windows usi l\'Utilità di pianificazione con programma {php2}, argomenti {args}, avvio in {path}.',
'Tg_Guide_N_Waiting' => '{n} in attesa di invio',
'Tg_Guide_Nothing_Waiting' => 'nulla in attesa',
'Tg_Guide_N_Gave_Up' => '{n} abbandonati dopo i tentativi',
'Tg_Guide_Growing_Hint' => '— se questo numero continua a crescere, la voce cron non è in esecuzione.',
'Tg_Guide_Without_Cron' => 'Senza la voce cron, tutto ciò che viene salvato in Stocky arriva comunque all\'istante; si perdono solo i nuovi tentativi e gli ordini importati.',
'Tg_Guide_Else_Title' => 'Tutto il resto',
'Tg_Guide_Else_Body' => 'I messaggi per gli eventi generati in background vengono consegnati dalla piattaforma — non c\'è nulla da configurare.',
'Tg_Guide_Not_Arrive' => 'Se non arriva',
'Tg_Guide_Err_401' => '{code} — il token del bot è errato. Lo incolli di nuovo da BotFather.',
'Tg_Guide_Err_400' => '{code} — chat ID errato, oppure il bot non è nel gruppo. Per una chat personale, scriva prima al bot.',
'Tg_Guide_Err_403' => '{code} — aggiunga di nuovo il bot al gruppo, oppure come amministratore del canale.',
'Tg_Guide_Test_Works' => 'Il test funziona ma le vendite no',
'Tg_Guide_Test_Works_Item' => '{label} — verifichi che l\'evento sia selezionato (oppure che sia scelto {allEvents}) e che l\'interruttore sia attivo.',
'Tg_Guide_Imported_Never' => 'Gli ordini importati non arrivano mai',
'Tg_Guide_Imported_Never_Item' => '{label} — la voce cron indicata sopra non è in esecuzione.',
'Jumia_Hero_Title' => 'Sincronizzazione marketplace Jumia',
'Jumia_Hero_Desc' => 'Invia prezzi e giacenze alle Sue inserzioni su Jumia Seller Center e importa gli ordini del marketplace come vendite.',
'Jumia_Api_Url_Label' => 'URL API (endpoint del Seller Center del Suo paese)',
'Jumia_Account_Email' => 'Email dell\'account (User ID)',
'Jumia_Prices_Stock' => 'Prezzi e giacenze',
'Jumia_Push_Card_Title' => 'Invia prezzi e giacenze a Jumia',
'Jumia_Push_Desc' => 'Invia il prezzo e la quantità attuali di ogni prodotto (e variante) con uno SKU corrispondente al {sellerSku} dell\'inserzione Jumia. Gli aggiornamenti vengono inviati come feed del Seller Center e applicati in modo asincrono — l\'ID del feed viene registrato nella scheda Log, e i rifiuti per singolo articolo compaiono nella schermata di stato dei feed del Seller Center.',
'Jumia_Push_Prices_Stock' => 'Invia prezzi e giacenze',
'Jumia_Orders_Desc' => 'Importa gli ordini del marketplace come vendite (riferimenti come {ref}), abbinati ai Suoi prodotti tramite Seller SKU. Gli ordini già importati e quelli annullati vengono saltati, quindi recuperarli regolarmente è sicuro. I pagamenti vengono segnati come pagati solo per gli ordini consegnati (su Jumia prevale il contrassegno).',
'Jumia_Guide_1' => 'In Jumia {sellerCenter} apra Settings → {integrationMgmt} e generi una chiave API.',
'Jumia_Guide_2' => 'Inserisca l\'URL API del Suo paese (ad es. {ng} per la Nigeria, {ke} per il Kenya, {eg} per l\'Egitto), l\'email del Suo account Seller Center e la chiave — quindi esegua {test}.',
'Jumia_Guide_3' => 'Si assicuri che il {sellerSku} di ogni inserzione Jumia corrisponda al codice prodotto di Stocky — è l\'identificativo usato sia per l\'invio delle giacenze sia per l\'abbinamento degli ordini.',
'Jumia_Guide_4' => 'Invii prezzi e giacenze dopo le variazioni di inventario; recuperi gli ordini regolarmente (in questa API Jumia non dispone di webhook).',
'Jumia_Guide_5' => 'La creazione di nuove inserzioni resta nel Seller Center — Jumia richiede attributi specifici per categoria e una revisione delle immagini che solo il suo portale gestisce bene.',
'Mc_Hero_Title' => 'Sincronizzazione pubblico Mailchimp',
'Mc_Hero_Desc' => 'Mantiene un pubblico Mailchimp popolato con i Suoi clienti, per condurre campagne email sulla Sua reale base clienti.',
'Mc_Account_Audience' => 'Account e pubblico',
'Mc_Api_Key_Placeholder' => 'es. a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Pubblico',
'Mc_N_Members' => '({n} membri)',
'Mc_Load_Audiences_To_Pick' => 'Carichi i pubblici per sceglierne uno',
'Mc_Load_Audiences' => 'Carica pubblici',
'Mc_Double_Opt_In_Label' => 'Double opt-in — i nuovi membri ricevono un\'email di conferma prima dell\'iscrizione',
'Mc_Recommended_GDPR' => '(consigliato per il GDPR)',
'Mc_Auto_Sync_New' => 'Sincronizza automaticamente i nuovi clienti al momento della creazione',
'Mc_With_Email' => 'Con email',
'Mc_Push_Desc' => 'Inserisce o aggiorna nel pubblico selezionato ogni cliente dotato di indirizzo email (nome e telefono inclusi). I membri esistenti mantengono il proprio stato di iscrizione — nessuno che si sia disiscritto viene reiscritto. I clienti senza email vengono esclusi.',
'Mc_Double_Opt_In_Off' => 'Il double opt-in è disattivato',
'Mc_Double_Opt_In_Off_Desc' => 'I nuovi membri verranno aggiunti come iscritti senza email di conferma. Lo faccia solo per clienti che hanno già acconsentito a ricevere comunicazioni di marketing.',
'Mc_Guide_1' => 'In Mailchimp apra {path} e crei una chiave (termina con {suffix} — quel suffisso è il Suo datacenter).',
'Mc_Guide_2' => 'Incolli qui la chiave, salvi, quindi faccia clic su {load} e scelga il pubblico da popolare.',
'Mc_Guide_3' => 'Lasci attivo il {doi}, a meno che i Suoi clienti non abbiano già acconsentito alle email di marketing.',
'Mc_Double_Opt_In_Lower' => 'double opt-in',
'Mc_Guide_4' => 'Esegua {push} per il popolamento iniziale; attivi la {autoSync} così che i nuovi clienti si aggiungano automaticamente.',
'Mc_Auto_Sync_Lower' => 'sincronizzazione automatica',
'Mc_Consent_Matters' => 'Il consenso è importante',
'Mc_Consent_Desc' => 'Inviare email a persone che non hanno mai acconsentito al marketing può violare il GDPR/CAN-SPAM e causare la sospensione del Suo account Mailchimp. Il double opt-in affida la conferma a Mailchimp — l\'impostazione predefinita sicura.',
'Mc_No_Audiences' => 'Nessun pubblico trovato in questo account.',
'Presta_Hero_Desc' => 'Sincronizza prodotti, giacenze e ordini con il Suo negozio PrestaShop tramite la sua API webservice.',
'Presta_Webservice_Key' => 'Chiave webservice',
'Presta_Key_Placeholder' => 'Da Parametri avanzati → Webservice',
'Presta_Key_Help' => 'Abiliti il webservice in PrestaShop (Parametri avanzati → Webservice), crei una chiave con permessi su products, stock_availables, orders e customers, e la incolli qui. Memorizzata in sola scrittura.',
'Presta_Shop_Language_ID' => 'ID lingua del negozio',
'Presta_Language_Help' => 'ID lingua usato per i nomi dei prodotti durante l\'invio (1 = la prima lingua del negozio).',
'Presta_Push_Desc' => 'Crea su PrestaShop i prodotti semplici mancanti (con la loro giacenza attuale). I prodotti già collegati e i prodotti con varianti vengono saltati — continui a modificare i dettagli dei prodotti in PrestaShop, oppure esegua un recupero per aggiornare la copia locale.',
'Presta_Pull_Desc' => 'Importa i prodotti PrestaShop, abbinando quelli esistenti tramite riferimento (SKU) e creando gli altri. Le combinazioni vengono importate come il relativo prodotto padre.',
'Presta_Reset_Confirm' => 'Reimpostare i collegamenti dei prodotti? Lo storico degli ordini mantiene i propri collegamenti.',
'Presta_Stock_Desc' => 'Aggiorna la giacenza del negozio (stock_availables) per ogni prodotto collegato.',
'Presta_Orders_Desc' => 'Importa gli ordini del negozio come vendite (riferimenti come {ref}), dal più recente. Gli ordini già importati e quelli annullati vengono saltati, quindi recuperarli regolarmente è sicuro. PrestaShop non dispone di webhook — lo esegua dopo i periodi di maggiore attività.',
'Presta_Guide_1' => 'Nel back office di PrestaShop apra {path} e abiliti il webservice.',
'Presta_Guide_2' => 'Aggiunga una nuova chiave, concedendo {vae} su {products} e {stock}, e {view} su {orders} e {customers}.',
'Presta_Guide_3' => 'Incolli l\'URL del negozio e la chiave nella scheda Connessione, salvi ed esegua {test}.',
'Presta_Guide_4' => 'Se il negozio ha già un catalogo, recuperi prima i prodotti (abbinamento per riferimento/SKU); invii per creare i prodotti semplici mancanti.',
'Presta_Guide_5' => 'Invii le giacenze ogni volta che le quantità cambiano e recuperi gli ordini regolarmente — PrestaShop non dispone di webhook, quindi gli ordini arrivano solo quando li recupera.',
'Presta_Identity_Title' => 'L\'identificativo del prodotto è il riferimento (SKU)',
'Presta_Identity_Desc' => 'Il codice prodotto di Stocky viene abbinato al riferimento di PrestaShop. Mantenga i riferimenti coerenti su entrambi i lati; le combinazioni (varianti) vengono abbinate negli ordini tramite riferimento, ma in questa versione non vengono inviate.',
'Gs_Hero_Title' => 'Esportazioni Google Sheets',
'Gs_Hero_Desc' => 'Esporta vendite, prodotti e clienti in un foglio di calcolo Google sempre aggiornato — una scheda ciascuno, aggiornata su richiesta.',
'Gs_OAuth_Credentials' => 'Credenziali Google OAuth',
'Gs_Secret_Placeholder' => 'Dal Suo client OAuth di Google Cloud',
'Gs_Auto_Export_Nightly' => 'Esportazione automatica notturna',
'Gs_Auto_Export_Hint' => '(tutte le schede aggiornate verso le 02:30 ora del server)',
'Gs_Enable_Exports' => 'Abilita le esportazioni Google Sheets',
'Gs_Account_Spreadsheet' => 'Account e foglio di calcolo',
'Gs_Connect' => 'Collega account Google',
'Gs_Reconnect' => 'Ricollega account Google',
'Gs_Disconnect_Confirm' => 'Scollegare l\'account Google? Le esportazioni si interrompono finché non lo ricollega.',
'Gs_Target_Spreadsheet' => 'Foglio di calcolo di destinazione (ID o URL completo)',
'Gs_Spreadsheet_Placeholder' => 'Incolli l\'URL di un foglio di calcolo, oppure ne crei uno →',
'Gs_Create_New' => 'Crea nuovo',
'Gs_Open_Spreadsheet' => 'Apri il foglio di calcolo ↗',
'Gs_Last_Export' => 'Ultima esportazione {date}',
'Gs_Redirect_Uri_Title' => 'URI di reindirizzamento per il client Google OAuth',
'Gs_Export_Desc' => 'Ogni esportazione riscrive la propria scheda da zero (intestazione + tutte le righe), quindi il foglio è sempre un\'istantanea completa e aggiornata. I grandi insiemi di dati vengono inviati a blocchi — lasci la pagina aperta finché il contatore non si ferma.',
'Gs_Export_Sales' => 'Esporta vendite',
'Gs_Export_Products' => 'Esporta prodotti',
'Gs_Export_Customers' => 'Esporta clienti',
'Gs_Job_Sales_Desc' => 'Ogni vendita con cliente, totali, stato del pagamento e magazzino.',
'Gs_Job_Products_Desc' => 'Il catalogo completo con prezzi, costi e quantità attuali in giacenza.',
'Gs_Job_Customers_Desc' => 'Tutti i clienti con i relativi recapiti.',
'Gs_Guide_1' => 'Crei un progetto su {console} e abiliti la {api} (APIs & Services → Library).',
'Gs_Guide_2' => 'Configuri la {consent} (External). Finché resta in "Testing", aggiunga il Suo account Google come utente di test: tenga presente che i refresh token in modalità di test scadono dopo 7 giorni, quindi per una connessione permanente occorre {publish} l\'app.',
'Gs_OAuth_Consent_Screen' => 'OAuth consent screen',
'Gs_Publish' => 'pubblicare',
'Gs_Guide_3' => 'Crei un {clientId} di tipo Web application e registri l\'URI di reindirizzamento indicato nella scheda Connessione.',
'Gs_OAuth_Client_ID' => 'OAuth client ID',
'Gs_Guide_4' => 'Incolli qui il Client ID e il Secret, salvi e faccia clic su {connect}.',
'Gs_Guide_5' => 'Crei un foglio di calcolo con il pulsante (oppure incolli l\'URL di uno che il Suo account Google può modificare), quindi esegua le esportazioni.',
'Gs_Snapshots_Title' => 'Istantanee, non sincronizzazione in tempo reale',
'Gs_Snapshots_Desc' => 'Le esportazioni riscrivono su richiesta le schede Sales / Products / Customers. Per aggiornamenti in tempo reale, riga per riga, a ogni vendita, colleghi Zapier: può aggiungere righe nel momento in cui si verificano gli eventi.',
'Gs_Connected_Spreadsheet' => 'Connesso — foglio di calcolo: {title}',
'Gs_Spreadsheet_Created' => 'Foglio di calcolo creato.',
'Gs_Account_Connected' => 'Account Google connesso.',
'Xero_Hero_Title' => 'Sincronizzazione contabile con Xero',
'Xero_Hero_Desc' => 'Invii i Suoi clienti come contatti Xero e le Sue vendite come fatture, con i pagamenti quando è configurato un conto bancario.',
'Xero_App_Credentials_Accounts' => 'Credenziali dell\'app e conti',
'Xero_From_Your_App' => 'Dalla Sua app su developer.xero.com',
'Xero_Sales_Account_Code' => 'Codice conto vendite',
'Xero_Sales_Account_Help' => 'Conto ricavi per le righe della fattura (\'200\' è il conto Vendite (Sales) predefinito di Xero).',
'Xero_Payment_Account_Code' => 'Codice conto pagamenti (facoltativo)',
'Xero_Payment_Code_Placeholder' => 'es. 090',
'Xero_Payment_Account_Help' => 'Un codice di conto bancario. Se impostato, per le vendite pagate viene registrato anche un pagamento sulla fattura; lasci vuoto per sincronizzare solo le fatture.',
'Xero_Auto_Sync' => 'Sincronizza automaticamente le nuove vendite come fatture',
'Xero_Auto_Sync_Hint' => '(messe in coda in background man mano che le vendite vengono create)',
'Xero_Org_Connection' => 'Connessione all\'organizzazione',
'Xero_Organisation' => 'Organizzazione',
'Xero_Disconnect_Confirm' => 'Disconnettere l\'organizzazione Xero? La sincronizzazione si interrompe finché non si riconnette.',
'Xero_Redirect_Uri_Title' => 'URI di reindirizzamento per l\'app Xero',
'Xero_Redirect_Help' => 'Crei una "Web app" su {link} e registri questo URI di reindirizzamento. Nota: i token di accesso Xero si rinnovano automaticamente, ma una connessione inattiva da oltre 60 giorni deve essere ricollegata.',
'Xero_Contacts_In_Xero' => 'Contatti in Xero',
'Xero_Invoices_In_Xero' => 'Fatture in Xero',
'Xero_Payments_Recorded' => 'Pagamenti registrati',
'Xero_Push_Customers_Desc' => 'Crea o aggiorna un contatto Xero per ogni cliente. Un cliente il cui nome esiste già in Xero viene collegato a quel contatto.',
'Xero_Push_Sales_As_Invoices' => 'Invia le vendite come fatture',
'Xero_Push_Invoices_Desc' => 'Crea una fattura AUTHORISED per ogni vendita (numero fattura = Rif. della vendita), con le righe articolo della vendita più le righe di spedizione, sconto e imposta, in modo che il totale in Xero corrisponda al totale della vendita. Le vendite già presenti in Xero vengono saltate: le fatture non vengono mai modificate. I contatti mancanti vengono creati al momento.',
'Xero_Push_Invoices' => 'Invia fatture',
'Xero_Reset_Contact_Confirm' => 'Reimpostare i collegamenti dei contatti? Il prossimo invio li ricollegherà o li ricreerà.',
'Xero_Reset_Contact_Links' => 'Reimposta collegamenti contatti',
'Xero_Guide_1' => 'Crei una {webApp} su {link} (My Apps → New app).',
'Xero_Web_App' => 'Web app',
'Xero_Guide_2' => 'Registri l\'URI di reindirizzamento indicato nella scheda Connessione.',
'Xero_Guide_3' => 'Copi il {clientId} dell\'app e generi un {clientSecret}; incolli entrambi qui e salvi.',
'Xero_Guide_4' => 'Faccia clic su {connect}, acceda e scelga l\'organizzazione da collegare.',
'Xero_Guide_5' => 'Verifichi i codici dei conti: il conto vendite riceve le righe delle fatture; imposti un codice di conto bancario se per le vendite pagate devono essere registrati anche i pagamenti.',
'Xero_Guide_6' => 'Invii prima i clienti, poi le fatture. I numeri delle fatture corrispondono ai Rif. delle vendite, quindi Xero rifiuta i duplicati anche se i collegamenti vengono reimpostati.',
'Xero_Tax_Inclusive_Title' => 'Gli importi vengono inviati così come sono, imposte incluse',
'Xero_Tax_Inclusive_Desc' => 'Le fatture usano righe NoTax che rispecchiano esattamente la vendita (articoli + spedizione − sconto + imposta), così i totali in Xero coincidono sempre con quelli di Stocky. Il Suo commercialista può riassegnare in Xero le righe di imposta e spedizione ai conti appropriati.',
'Xero_Org_Connected' => 'Organizzazione Xero connessa.',
'Salla_Hero_Desc' => 'Sincronizzi prodotti, giacenze e ordini con il Suo negozio Salla: gli ordini arrivano automaticamente tramite webhook.',
'Salla_App_Credentials' => 'Credenziali dell\'app',
'Salla_From_Partners_App' => 'Dalla Sua app Salla Partners',
'Salla_Webhook_Secret' => 'Webhook Secret',
'Salla_Webhook_Secret_Placeholder' => 'Secret di firma dalla pagina Webhooks della Sua app',
'Salla_Token_Expires' => 'Scadenza del token',
'Salla_Disconnect_Confirm' => 'Disconnettere il negozio Salla? La sincronizzazione si interrompe finché non si riconnette.',
'Salla_Urls_Title' => 'URL per il portale Salla Partners',
'Salla_OAuth_Callback' => 'Callback OAuth',
'Salla_Webhook_Url_All' => 'URL webhook (tutti gli eventi)',
'Salla_Urls_Help' => 'Imposti entrambi nella Sua app su {link}, scelga la strategia di sicurezza webhook {signature} e sottoscriva gli eventi relativi a ordini, prodotti e app.',
'Salla_Variants_Linked' => 'Varianti collegate',
'Salla_Push_Desc' => 'Crea o aggiorna i prodotti semplici su Salla tramite SKU. In questa versione i prodotti con varianti vengono saltati: li recuperi da Salla oppure li abbini tramite SKU.',
'Salla_Only_Unlinked' => 'Solo i prodotti non ancora collegati',
'Salla_Pull_Desc' => 'Importa i prodotti Salla (varianti incluse), abbinando quelli esistenti tramite SKU e creando gli altri.',
'Salla_Reset_Confirm' => 'Reimpostare i collegamenti di prodotti e varianti? Lo storico degli ordini mantiene i propri collegamenti.',
'Salla_Stock_Desc' => 'Invia le quantità attuali di ogni prodotto collegato (tramite SKU) e di ogni variante collegata.',
'Salla_Orders_Desc' => 'I nuovi ordini Salla di norma arrivano da soli tramite webhook e diventano vendite. Usi questo recupero per importare gli ordini effettuati prima della configurazione del webhook: gli ordini già importati vengono saltati.',
'Salla_Guide_1' => 'Crei un\'app (privata) su {link} e scelga il flusso di autorizzazione {mode}.',
'Salla_Guide_2' => 'Copi il {clientId} e il {clientSecret} dell\'app nella scheda Connessione e salvi.',
'Salla_Guide_3' => 'Nelle impostazioni dell\'app, imposti l\'URL di callback OAuth indicato nella scheda Connessione.',
'Salla_Guide_4' => 'Nella pagina Webhooks dell\'app: scelga la strategia di sicurezza {signature}, copi il relativo secret nel campo Webhook Secret qui, imposti l\'URL webhook indicato nella scheda Connessione e sottoscriva almeno {e1}, {e2}, {e3}, {e4}, {e5} e {e6}.',
'Salla_Guide_5' => 'Faccia clic su {connect} e approvi l\'app nel Suo negozio. (Le app in Easy Mode si collegano invece automaticamente tramite il webhook {webhook}.)',
'Salla_Guide_6' => 'Recuperi o invii i prodotti, quindi invii le giacenze. I nuovi ordini arrivano automaticamente e compaiono in Vendite con riferimenti come {ref}.',
'Salla_Identity_Title' => 'L\'identità del prodotto è lo SKU',
'Salla_Identity_Desc' => 'Il codice prodotto di Stocky viene abbinato allo SKU di Salla. Mantenga gli SKU coerenti su entrambi i lati; i prodotti con varianti vengono abbinati nel recupero e negli ordini, ma in questa versione non vengono inviati.',
'Salla_Store_Connected' => 'Negozio Salla connesso.',

