'Fbr_Page_Title' => 'FBR Digital Invoicing (Pakistan)',
'Fbr_Token_Saved' => 'È salvato un token (••••{last4}). Lasci vuoto per mantenerlo.',
'Fbr_Token_Obtain' => 'Ottenga il token dal portale di fatturazione elettronica PRAL / IRIS.',
'Fbr_Token_Placeholder' => 'Incolli il token dal portale di fatturazione elettronica PRAL / IRIS',
'Fbr_Guide_What_Title' => 'Che cos\'è FBR Digital Invoicing?',
'Fbr_Guide_What_Body' => 'In base allo SRO 69(I)/2025, il Federal Board of Revenue (Pakistan) richiede alle imprese integrate di trasmettere le fatture di vendita elettronicamente e in tempo reale tramite l\'API PRAL Digital Invoicing (DI). Ogni vendita accettata riceve un numero di fattura FBR ufficiale e le ricevute devono riportare tale numero insieme a un codice QR di verifica.',
'Fbr_Guide_Steps_Title' => 'Passaggi per andare in produzione',
'Fbr_Guide_Step_1' => 'Si registri sul portale di fatturazione elettronica FBR IRIS e ottenga un security token {sandbox}.',
'Fbr_Guide_Step_2' => 'Configuri il profilo del venditore nella scheda Configurazione (NTN/CNIC, ragione sociale, provincia, indirizzo), incolli il token e abiliti l\'integrazione con l\'ambiente impostato su {sandbox}.',
'Fbr_Guide_Step_3' => 'Effettui vendite di prova che coprano gli scenari assegnatiLe da FBR (scelga lo scenario nel campo Scenario sandbox). Controlli la scheda Documenti per verificare che risultino {valid}.',
'Fbr_Guide_Step_4' => 'Una volta che FBR ha approvato i test in sandbox, ottenga il token di {production} dal portale, lo incolli qui e imposti l\'ambiente su {production}.',
'Fbr_Guide_Step_5' => 'Le ricevute mostrano automaticamente il numero di fattura FBR e il codice QR una volta accettata la vendita: non sono necessari passaggi aggiuntivi alla cassa.',
'Fbr_Sandbox_Lower' => 'sandbox',
'Fbr_Production_Lower' => 'produzione',
'Fbr_Guide_Note_1' => 'Imposti i codici HS per ciascun prodotto nel modulo del prodotto (campo "Codice HS"). Il codice HS predefinito configurato qui viene usato solo per i prodotti che ne sono privi.',
'Fbr_Guide_Note_2' => 'I clienti occasionali non registrati vengono comunicati a FBR come "Unregistered".',
'Fbr_Guide_Note_3' => 'Gli acquirenti registrati devono avere il proprio NTN inserito nel campo Numero fiscale del cliente, affinché vengano comunicati come registrati.',
'Fbr_Guide_Note_4' => 'Gli invii non riusciti o non validi possono essere ritentati dalla scheda Documenti dopo averne corretto la causa; la scheda Log mostra gli scambi API grezzi per la risoluzione dei problemi.',
