'Woo_WordPress_Username' => 'Nome utente WordPress',
'Woo_WordPress_App_Password' => 'Password per le applicazioni WordPress',
'Woo_Automatic_Sync' => 'Sincronizzazione automatica',
'Woo_Auto_Sync_Intro' => 'Invia a WooCommerce le modifiche apportate in Stocky nel momento in cui avvengono, senza aprire questa pagina. Ogni invio parte subito dopo il salvataggio dell\'operazione, quindi il cassiere non attende mai WooCommerce. I risultati compaiono nella scheda Log.',
'Woo_Auto_Sync_Products_Help' => 'Un prodotto creato, modificato o duplicato in Stocky viene inviato a WooCommerce (dettagli, prezzo, varianti, immagini, giacenza). Le importazioni massive non vengono inviate; dopo un\'importazione, usi Sincronizza — POS verso WooCommerce nella scheda Prodotti.',
'Woo_Auto_Sync_Stock_Help' => 'Qualsiasi movimento di giacenza (vendita POS, vendita, reso, acquisto, rettifica, trasferimento) aggiorna su WooCommerce la quantità dei prodotti interessati. Vengono aggiornati solo i prodotti già collegati a WooCommerce.',
'Woo_Sync_Tuning' => 'Ottimizzazione della sincronizzazione',
'Woo_Sync_Tuning_Intro' => 'I valori predefiniti vanno bene per la maggior parte dei negozi. Li modifichi solo se la sincronizzazione è lenta o va in timeout sul suo hosting. Ogni valore è limitato a un intervallo sicuro e svuotando un campo si ripristina il valore predefinito.',
'Woo_Sync_Guide' => 'Guida alla sincronizzazione WooCommerce',
'Woo_Guide_Getting_Keys' => 'Ottenere le chiavi API',
'Woo_Guide_Keys_1' => 'In WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Clicchi Add key, scelga Read/Write, quindi copi Consumer key e Consumer secret.',
'Woo_Guide_Keys_3' => 'URL del negozio: l\'URL del suo sito senza barra finale (es. {example}).',
'Woo_Guide_WP_Title' => 'Nome utente WP e password per le applicazioni (facoltativi)',
'Woo_Guide_WP_Intro' => 'Questi campi servono solo per le immagini dei prodotti. L\'API di WooCommerce (URL del negozio + Consumer key/secret) gestisce la sincronizzazione di prodotti, giacenze, categorie, marche, clienti e ordini; la REST API di WordPress gestisce la Libreria media (ricerca e caricamento delle immagini).',
'Woo_Guide_WP_1' => 'Durante la sincronizzazione di prodotti o giacenze, Stocky può allegare le immagini dei prodotti: prima cerca nella Libreria media di WordPress un\'immagine esistente con lo stesso nome file; se non la trova, carica l\'immagine tramite l\'API di WordPress.',
'Woo_Guide_WP_2' => 'Usi un utente WordPress in grado di gestire i media (es. Administrator). Crei una password per le applicazioni in WordPress: Users → Profile (o il suo utente) → Application Passwords — ne aggiunga una nuova e la incolli qui.',
'Woo_Guide_WP_3' => 'Se lascia vuoti questi campi, la sincronizzazione funziona comunque per tutti i dati (prodotti, giacenze, categorie, marche, clienti, ordini); viene saltato solo l\'allegato delle immagini dei prodotti (ricerca/caricamento).',
'Woo_Guide_How_To_Enable' => 'Come attivarla',
'Woo_Guide_Enable_1' => 'Inserisca sopra URL del negozio, Consumer key e Consumer secret, quindi clicchi Salva.',
'Woo_Guide_Enable_2' => 'Usi Testa la connessione per verificare le credenziali.',
'Woo_Guide_Enable_3' => 'Usi la sincronizzazione manuale da qualsiasi scheda quando deve sincronizzare.',
'Woo_Guide_Enable_4' => 'Attivi sopra la Sincronizzazione automatica per inviare a WooCommerce i prodotti nuovi e modificati e ogni variazione di giacenza nel momento in cui avvengono.',
'Woo_Guide_Manual_Sync' => 'Sincronizzazione manuale (su richiesta)',
'Woo_Guide_Manual_1' => 'La sincronizzazione funziona in entrambe le direzioni: Stocky → WooCommerce e WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'La sincronizzazione manuale è disponibile in tutte le schede WooCommerce (Prodotti, Giacenze, ecc.); usi le azioni di sincronizzazione di ciascuna scheda per eseguirla su richiesta.',
'Woo_Guide_Auto_1' => 'Prodotti: se attiva, un prodotto creato, modificato o duplicato in Stocky viene inviato a WooCommerce subito dopo il salvataggio, seguito dalla sua giacenza.',
'Woo_Guide_Auto_2' => 'Giacenze: se attiva, ogni variazione di giacenza (vendita POS, vendita, reso, acquisto, rettifica, trasferimento) aggiorna la quantità su WooCommerce. Vengono aggiornati solo i prodotti già collegati a WooCommerce.',
'Woo_Guide_Auto_3' => 'La sincronizzazione automatica invia le modifiche solo da Stocky a WooCommerce. L\'importazione dei dati da WooCommerce in Stocky (ordini, clienti, prodotti) avviene sempre con i pulsanti delle schede Ordini, Clienti e Prodotti.',
'Woo_Guide_Auto_4' => 'Le importazioni massive di prodotti non vengono inviate automaticamente. Dopo un\'importazione, usi Sincronizza — POS verso WooCommerce nella scheda Prodotti.',
'Woo_Guide_Auto_5' => 'Ogni invio automatico viene registrato nella scheda Log, così può verificare cosa è stato inviato e individuare gli errori.',
'Woo_Guide_First_Setup' => 'Prima configurazione',
'Woo_Guide_First_1' => 'Esegua queste operazioni una sola volta, in quest\'ordine, per collegare il catalogo esistente: Sincronizza — POS verso WooCommerce nella scheda Categorie, poi nella scheda Marca, poi nella scheda Prodotti e infine Sincronizza giacenze nella scheda Giacenze. Dopodiché attivi sopra la Sincronizzazione automatica per mantenere WooCommerce aggiornato.',
'Woo_Guide_First_2' => 'Le sincronizzazioni di grandi quantità di prodotti e giacenze vengono eseguite in piccoli lotti e mostrano l\'avanzamento nella scheda. Tenga la pagina aperta finché la sincronizzazione non termina; può interromperla in qualsiasi momento.',
'Woo_Guide_First_3' => 'Se una sincronizzazione resta ferma per diversi minuti, controlli la scheda Log, quindi contatti l\'assistenza.',
'Woo_Guide_Notes_1' => 'La modifica dell\'URL del negozio o delle chiavi API azzera le mappature (prodotti, categorie, marche, clienti); gli elementi verranno sincronizzati di nuovo verso il (nuovo) negozio.',
'Woo_Guide_Notes_2' => 'Mantenga gli SKU coerenti tra Stocky e WooCommerce per evitare prodotti duplicati e ricollegarli in sicurezza.',
