'Pg_Gateway_Switched_Off' => '{name} è disattivato',
'Pg_Credentials_Kept' => 'Le sue credenziali vengono conservate — il checkout del negozio online smette semplicemente di proporre {name} finché non lo riattiva.',
'Pg_Remove_Credentials_Confirm' => 'Rimuovere le credenziali {name} memorizzate? Il checkout smetterà di proporre {short}.',
'Pg_Remove_Keys_Confirm' => 'Rimuovere le chiavi {name} memorizzate? Il checkout smetterà di proporre {short}.',
'Pg_Sandbox_Test_Mode' => 'Sandbox (modalità test)',
'Pg_Stripe_Shared_Notice' => 'Le chiavi Stripe sono condivise da tutto il sistema.',
'Pg_Store_Feature_Not_In_Plan' => 'I gateway del negozio online e i metodi di pagamento offline fanno parte della funzionalità Ordini online, non inclusa nel suo piano attuale.',
'Pg_Intro_Title' => 'Ogni gateway qui presente viene proposto al checkout del NEGOZIO ONLINE una volta memorizzate le sue credenziali e attivato il relativo interruttore.',
'Pg_Intro_Desc' => 'Ogni scheda ha il proprio interruttore di attivazione, salvato nel momento in cui lo aziona: disattivando un gateway le credenziali restano memorizzate, il checkout smette semplicemente di proporlo. Le chiavi Stripe sono condivise a livello globale (amministrazione e negozio online usano la stessa integrazione Stripe). Pagamenti offline comprende il contrassegno e il mobile money, che vengono pagati al di fuori del sistema.',
'Pg_Label_Stripe_Key' => 'CHIAVE STRIPE',
'Pg_Label_Stripe_Secret' => 'SEGRETO STRIPE',
'Pg_Card_Payments_Off' => 'I pagamenti con carta sono disattivati',
'Pg_Card_Keys_Kept' => 'Le sue chiavi vengono conservate — il checkout del negozio online smette semplicemente di proporre il pagamento con carta finché non lo riattiva.',
'Pg_No_Stripe_Key' => 'Nessuna chiave Stripe memorizzata',
'Pg_Enter_Stripe_Key' => 'Inserisca la chiave e il segreto Stripe per iniziare ad accettare pagamenti con carta nel negozio online.',
'Pg_Label_Razorpay_Key_Id' => 'RAZORPAY KEY ID',
'Pg_Label_Razorpay_Key_Secret' => 'RAZORPAY KEY SECRET',
'Pg_Razorpay_Help' => 'Usa Razorpay Checkout nel negozio online (carte, UPI, netbanking, wallet). La modalità test o live è determinata dalla coppia di chiavi (rzp_test_/rzp_live_) — non esiste un interruttore sandbox separato. Il checkout propone Razorpay non appena entrambe le chiavi sono memorizzate.',
'Pg_Label_Bkash_App_Key' => 'BKASH APP KEY',
'Pg_Label_Bkash_App_Secret' => 'BKASH APP SECRET',
'Pg_Label_Bkash_Username' => 'NOME UTENTE BKASH',
'Pg_Label_Bkash_Password' => 'PASSWORD BKASH',
'Pg_Bkash_Sandbox_Help' => 'ATTIVO usa tokenized.sandbox.bka.sh con le sue credenziali sandbox; lo DISATTIVI per addebitare conti bKash reali su tokenized.pay.bka.sh.',
'Pg_Bkash_Help' => 'Usa bKash Tokenized Checkout (credenziali commerciante dal portale commercianti bKash). Addebita in BDT. Il checkout propone bKash non appena tutte e quattro le credenziali sono memorizzate.',
'Pg_Label_Sslcommerz_Store_Id' => 'SSLCOMMERZ STORE ID',
'Pg_Label_Sslcommerz_Store_Password' => 'SSLCOMMERZ STORE PASSWORD',
'Pg_Sslcommerz_Sandbox_Help' => 'ATTIVO usa sandbox.sslcommerz.com con credenziali sandbox; lo DISATTIVI per addebitare clienti reali su securepay.sslcommerz.com.',
'Pg_Sslcommerz_Help' => 'Checkout ospitato che copre carte, mobile banking bKash/Nagad/Rocket e internet banking in Bangladesh. Addebita in BDT.',
'Pg_Sslcommerz_Ipn_Help' => 'URL IPN (protezione di riserva consigliata — lo imposti in My Stores → IPN Settings nel pannello commercianti SSLCommerz):',
'Pg_Label_Region' => 'REGIONE',
'Pg_Paymob_Region_Help' => 'Paese del suo account Paymob: egypt, ksa, uae, pakistan o oman (seleziona l\'host API; predefinito: egypt).',
'Pg_Label_Public_Key' => 'CHIAVE PUBBLICA',
'Pg_Label_Secret_Key' => 'CHIAVE SEGRETA',
'Pg_Label_Api_Key' => 'CHIAVE API',
'Pg_Label_Integration_Ids' => 'INTEGRATION ID',
'Pg_Paymob_Integration_Help' => 'Da Paymob Dashboard → Developers → Payment Integrations; ne separi più di uno con una virgola per proporre più metodi.',
'Pg_Paymob_Integration_Placeholder' => 'es. 4419544 oppure 4419544,4419545',
'Pg_Label_Hmac_Secret' => 'SEGRETO HMAC',
'Pg_Label_Charge_Currency' => 'VALUTA DI ADDEBITO',
'Pg_Paymob_Currency_Help' => 'Deve corrispondere alla valuta del suo account Paymob (EGP, SAR, AED, PKR o OMR) e alla valuta base del suo negozio.',
'Pg_Paymob_Help' => 'Usa Paymob Unified Checkout (carte, wallet e metodi locali in Egitto, Arabia Saudita, EAU, Pakistan e Oman). Tutte e cinque le credenziali si trovano in Paymob Dashboard → Settings → Account Info + Payment Integrations.',
'Pg_Paymob_Webhook_Help' => 'Il webhook viene impostato automaticamente per ogni pagamento — non serve alcuna configurazione nella dashboard. URL di callback di riserva, per riferimento:',
'Pg_Label_Api_Token' => 'TOKEN API',
'Pg_Label_Account_Country_Live' => 'PAESE DELL\'ACCOUNT (LIVE)',
'Pg_Myfatoorah_Country_Help' => 'Codice ISO del paese del suo account MyFatoorah — KWT, SAU, QAT, EGY, ARE, BHR, OMN o JOR. Seleziona l\'host dell\'API live; ignorato in modalità sandbox.',
'Pg_Myfatoorah_Currency_Help' => 'Deve corrispondere alla valuta del suo account MyFatoorah (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) e alla valuta base del suo negozio.',
'Pg_Myfatoorah_Sandbox_Help' => 'ATTIVO usa apitest.myfatoorah.com con un token API demo; lo DISATTIVI per addebitare clienti reali sull\'API live.',
'Pg_Myfatoorah_Help' => 'Link di fattura ospitato che copre KNET, mada, carte, Apple Pay e STC Pay in tutta l\'area del Golfo (GCC). Il token API si trova in MyFatoorah Vendor Portal → Integration Settings → API Key.',
'Pg_Moyasar_Currency_Help' => 'SAR per impostazione predefinita — deve corrispondere alla valuta base del suo negozio.',
'Pg_Moyasar_Help' => 'Pagina di fattura ospitata che copre mada, carte di credito, Apple Pay e STC Pay in Arabia Saudita. Usi una chiave sk_test_ per la sandbox — Moyasar non ha un host di test separato.',
'Pg_Label_Account_Id' => 'ID ACCOUNT',
'Pg_Xpay_Account_Help' => 'XPay Dashboard > Settings > Store Info.',
'Pg_Xpay_Account_Placeholder' => 'L\'ID del suo account XPay',
'Pg_Label_Publishable_Key' => 'PUBLISHABLE KEY',
'Pg_Xpay_Publishable_Help' => 'Settings > Store Info > Key Details > API Keys — usata dall\'elemento carta nel browser.',
'Pg_Label_Api_Hmac_Secret' => 'SEGRETO HMAC API',
'Pg_Xpay_Hmac_Placeholder' => 'Key Details > HMAC Keys',
'Pg_Label_Webhook_Hmac_Secret' => 'SEGRETO HMAC WEBHOOK',
'Pg_Label_Webhook_Url' => 'URL WEBHOOK',
'Pg_Xpay_Webhook_Help' => 'Incolli questo URL in XPay Dashboard > Settings > Store Info > Webhook URL.',
'Pg_Xpay_Currency_Help' => 'PKR — deve corrispondere alla valuta base del suo negozio.',
'Pg_Xpay_Sandbox_Help' => 'ATTIVO usa xstak-pay-stg.xstak.com con le sue chiavi di staging; lo DISATTIVI (e memorizzi le chiavi live) per addebitare clienti reali.',
'Pg_Xpay_Help' => 'I dati della carta vengono inseriti in un elemento XPay incorporato nella pagina di checkout (nessun reindirizzamento). Ogni pagamento viene riverificato lato server prima della creazione dell\'ordine. Nota: l\'SDK di XPay richiede il segreto HMAC API nel browser, come nei plugin ufficiali di XPay.',
'Pg_Label_Payfast_Merchant_Id' => 'PAYFAST MERCHANT ID',
'Pg_Label_Payfast_Merchant_Key' => 'PAYFAST MERCHANT KEY',
'Pg_Label_Payfast_Passphrase' => 'PAYFAST PASSPHRASE',
