'Shp_Name_Hint' => 'Come viene etichettato questo negozio nell\'ERP',
'Shp_Name_Placeholder' => 'es. Negozio online principale',
'Shp_Domain_Hint' => '{domain} — funziona anche l\'URL di amministrazione',
'Shp_App_Credentials' => 'Credenziali dell\'app',
'Shp_Auth_Client_Credentials' => 'Client ID + client secret (app Dev Dashboard)',
'Shp_Auth_Token' => 'Token di accesso Admin API (app personalizzata legacy)',
'Shp_Cc_Alert' => 'Da gennaio 2026 Shopify non crea più app personalizzate nell\'amministrazione. Crei l\'app nella {dashboard}, conceda i relativi scope Admin API, la installi su questo negozio, quindi copi Client ID e Client secret dalla sua pagina {settings}. L\'ERP ottiene autonomamente un nuovo token di accesso ogni 24 ore. L\'app e il negozio devono appartenere alla stessa organizzazione Shopify.',
'Shp_Leave_Blank_Keep_Stored' => 'Lasci vuoto per mantenere quello memorizzato.',
'Shp_Client_Id_Placeholder' => 'Dalla pagina Settings dell\'app',
'Shp_Client_Secret_Hint' => 'Firma anche i webhook, quindi non serve un segreto di firma separato.',
'Shp_Masked_Unchanged' => '•••••••••••••• (invariato)',
'Shp_Token_Keep_Hint' => 'Lasci vuoto per mantenere il token già memorizzato.',
'Shp_Token_Legacy_Hint' => 'Solo per le app personalizzate create nell\'amministrazione Shopify prima del 2026 (Apps → Develop apps → API credentials). Le nuove app non mostrano un token; usi invece client ID + secret.',
'Shp_Webhook_Signing_Secret' => 'Segreto di firma dei webhook',
'Shp_Webhook_Secret_Optional_Hint' => 'Facoltativo qui — per un\'app Dev Dashboard i webhook vengono firmati dal client secret indicato sopra.',
'Shp_Webhook_Secret_Required_Hint' => 'Obbligatorio perché i webhook vengano accettati — le consegne non firmate vengono rifiutate.',
'Shp_Will_Be_Cleared' => 'Verrà cancellato al salvataggio',
'Shp_Clear_Stored_Secret' => 'Cancella il segreto memorizzato',
'Shp_Keep_It' => 'Non cancellare',
'Shp_Domain_Locked' => 'Il dominio è bloccato perché modificarlo invalida tutte le mappature di questo negozio.',
'Shp_Change_Anyway' => 'Modifica comunque',
'Shp_Domain_Change_Warning' => 'Salvando un dominio diverso vengono eliminate tutte le mappature dei record per questa connessione — gli ID memorizzati appartengono al negozio precedente.',
'Shp_ERP_Warehouse' => 'Magazzino ERP',
'Shp_ERP_Warehouse_Hint' => 'Le giacenze e gli ordini importati appartengono a questo magazzino.',
'Shp_Available_After_Connecting' => 'Disponibile dopo il collegamento',
'Shp_Fetch_Locations' => 'Recupera le sedi da Shopify',
'Shp_Price_Sent' => 'Prezzo inviato a Shopify',
'Shp_Create_Missing_Products' => 'Crea prodotti ERP per i prodotti Shopify che non corrispondono a uno SKU',
'Shp_Create_Missing_Customers' => 'Crea clienti ERP per i clienti Shopify che non corrispondono a un\'email',
'Shp_Create_Missing_Customers_Hint' => 'Se disattivato, un ordine di un cliente sconosciuto viene ignorato anziché associato per approssimazione.',
'Shp_Entities_Lead' => 'Possono essere sincronizzate solo le entità attivate qui — un negozio da cui recupera solo gli ordini non dovrebbe vedersi riscrivere il catalogo da un invio di prodotti accidentale.',
'Shp_Sync_On_Schedule' => 'Sincronizza automaticamente secondo una pianificazione',
'Shp_Scheduler_Hint' => 'Il pianificatore controlla ogni 5 minuti, che è la granularità minima utilizzabile dagli intervalli qui sotto. Le sincronizzazioni possono sempre essere avviate manualmente.',
'Shp_Instant_Push_Hint' => 'Una vendita, un reso o una rettifica invia la giacenza dei soli prodotti interessati nel momento in cui viene salvata, così il negozio è aggiornato entro pochi secondi invece che alla prossima esecuzione pianificata. Nient\'altro da installare — l\'invio avviene dopo che la vendita ha ricevuto risposta, quindi la cassa non attende mai Shopify.',
'Shp_Switch_Inventory_First' => 'Attivi prima Inventario in {tab}.',
'Shp_Leave_Off_Lag' => 'Se lo lascia disattivato, una vendita POS arriva a Shopify solo al successivo invio dell\'inventario — fino a {n} minuti dopo.',
'Shp_Default_Interval' => 'Intervallo predefinito (minuti)',
'Shp_Default_Interval_Hint' => 'Usato da ogni passaggio che non ne imposta uno proprio.',
'Shp_What_Runs_Auto' => 'Cosa viene eseguito automaticamente',
'Shp_Plan_Hint' => 'Ogni passaggio corrisponde a un\'entità in una direzione. Gli ordini arrivano sempre e solo {from} Shopify.',
'Shp_From' => 'da',
'Shp_Add_Step' => 'Aggiungi passaggio',
'Shp_Using_Default_Plan' => 'Piano predefinito in uso',
'Shp_Default_Plan_Desc' => 'Gli ordini vengono recuperati e la giacenza viene inviata ogni {n} minuti. Aggiunga un passaggio per definire un piano personalizzato — svuotando di nuovo l\'elenco si ripristina questo piano predefinito.',
'Shp_N_Min' => '{n} min',
'Shp_Step_Entity_Off' => '{entity} è disattivato nella scheda precedente — questo passaggio verrà saltato.',
'Shp_Inactive_Lc' => 'inattivo',
'Shp_No_Locations' => 'Il negozio non segnala alcuna sede',
'Shp_Could_Not_Load_Locations' => 'Impossibile caricare le sedi — verifichi prima la connessione',
'Shp_Store_Updated' => 'Negozio aggiornato',
'Shp_Store_Connected' => 'Negozio collegato',
'Shp_Could_Not_Save_Store' => 'Impossibile salvare questo negozio',
'Shp_G_Lead_Store' => 'Ciò di cui questo negozio ha bisogno per restare allineato. Tutto ciò che vede qui è specifico di questo negozio — l\'URL del webhook e gli ID sono reali.',
'Shp_G_Lead_Store_Cmd' => 'Ciò di cui questo negozio ha bisogno per restare allineato. Tutto ciò che vede qui è specifico di questo negozio — l\'URL del webhook e gli ID sono reali, quindi i comandi possono essere copiati direttamente sul server.',
'Shp_G_Lead_Generic' => 'Come un negozio Shopify resta allineato con l\'ERP. Scelga un negozio qui sopra per vederne lo stato, oppure legga la guida così com\'è — l\'URL del webhook è lo stesso qualunque negozio colleghi.',
'Shp_G_Lead_Generic_Cron' => 'Come un negozio Shopify resta allineato con l\'ERP. Scelga un negozio qui sopra per vederne lo stato, oppure legga la guida così com\'è — l\'URL del webhook e la riga cron sono gli stessi qualunque negozio colleghi.',
'Shp_G_Ways_Note' => 'La maggior parte dei negozi usa entrambe le modalità: la prima mantiene il negozio aggiornato minuto per minuto, la seconda recupera ciò che la prima ha perso — un webhook mai arrivato, una modifica fatta direttamente nell\'amministrazione Shopify, una notte in cui il sito era offline.',
'Shp_G_Both_Need' => 'Entrambe le modalità richiedono prima questo',
'Shp_G_Credentials' => 'Credenziali Shopify',
'Shp_G_Cred_Intro' => 'Da gennaio 2026 Shopify non crea più app personalizzate all\'interno dell\'amministrazione, quindi esistono due tipi di connessione:',
'Shp_G_Cred_Dev' => '{app} (qualsiasi negozio collegato ora) — {path}. Conceda gli scope Admin API per ciò che questo negozio sincronizza, installi l\'app sul negozio, quindi copi {clientId} e {clientSecret} dalla pagina Settings dell\'app in {edit}. L\'ERP li scambia autonomamente con un token di accesso e lo rinnova prima della scadenza, ogni 24 ore. Il client secret firma anche i webhook, quindi non serve altro. L\'app e il negozio devono trovarsi nella stessa organizzazione Shopify.',
'Shp_G_Dev_App' => 'App Dev Dashboard',
'Shp_G_Cred_Legacy' => '{app} (creata nell\'amministrazione prima del 2026) — continua a funzionare invariata con il suo {token} ({prefix}) e la sua {secret} come segreto di firma dei webhook. Non è lo stesso valore del token, e scambiarli è il motivo più comune per cui i webhook vengono rifiutati.',
'Shp_G_Legacy_App' => 'App personalizzata legacy',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'memorizzato',
'Shp_G_Missing_Refused' => 'mancante — le consegne verranno rifiutate',
'Shp_G_Targets' => '{path} Il magazzino ERP le cui giacenze sono vendute da questo negozio e la sede Shopify in cui tali giacenze vengono scritte. La sincronizzazione dell\'inventario e l\'importazione degli ordini non vengono eseguite senza di essi.',
'Shp_G_Currently' => 'Attualmente: magazzino {warehouse}, sede {location}',
'Shp_G_Not_Set_Lc' => 'non impostato',
'Shp_G_Ready' => 'pronto',
'Shp_G_Incomplete' => 'incompleto',
'Shp_G_Manual_Syncs' => 'Sincronizzazioni avviate manualmente',
'Shp_G_Manual_Body' => 'Una sincronizzazione avviata dal {centre} risponde subito e viene eseguita in background, in brevi porzioni che riprendono ciascuna dal punto in cui si è fermata la precedente. Un catalogo di grandi dimensioni non viene mai interrotto a metà da una richiesta web che va in timeout, e chiudere la pagina non la interrompe.',
'Shp_G_Worker_Managed' => 'La sua piattaforma esegue già il worker necessario, quindi non c\'è nulla da installare.',
'Shp_G_Worker_Cron' => 'Il worker necessario è un\'ulteriore riga cron:',
'Shp_G_Cron_Copied' => 'Riga cron copiata',
'Shp_G_Worker_Busy' => 'Se il worker è occupato, la pagina del Centro di sincronizzazione aperta porta avanti l\'esecuzione da sola dopo qualche secondo, una breve richiesta alla volta — così una sincronizzazione termina sempre mentre la osserva.',
'Shp_G_Pick_How' => 'Poi scelga come restare allineati',
'Shp_G_Right_Away' => 'In tempo reale',
'Shp_G_Stock_Live' => 'giacenza in tempo reale',
'Shp_G_Stock_Not_Live' => 'giacenza non in tempo reale',
'Shp_G_Realtime_Lead' => 'Ogni modifica viene inviata nel momento in cui avviene, in pochi secondi. Due metà, con interruttori separati: i {webhooks} portano all\'interno gli eventi del negozio e l\'{push} invia la giacenza all\'esterno.',
'Shp_G_Webhooks_Lc' => 'webhook',
'Shp_G_Instant_Push_Lc' => 'invio istantaneo della giacenza',
'Shp_G_Webhooks_Heading' => 'Webhook — dal negozio all\'ERP',
'Shp_G_Webhooks_Body' => 'Ordini, variazioni di stato degli ordini e modifiche a prodotti, clienti e giacenze effettuate in Shopify. Apra il negozio e prema {button} nella sua {tab} — si può premere due volte senza problemi. Shopify invia a:',
'Shp_G_Webhooks_Tab' => 'scheda Webhook',
'Shp_G_Webhooks_Note' => 'L\'indirizzo deve essere raggiungibile da Internet tramite HTTPS — Shopify non effettua consegne a {localhost} o a un dominio {test}. Ogni consegna viene registrata una sola volta, quindi i nuovi tentativi di Shopify non possono creare un ordine duplicato, e una consegna non riuscita può essere rieseguita. Le consegne vengono rifiutate finché non viene memorizzato il segreto di firma del passaggio 1.',
'Shp_G_Push_Heading' => 'Invio istantaneo della giacenza — dall\'ERP al negozio',
'Shp_G_People_Miss' => 'Questa è l\'impostazione che spesso sfugge',
'Shp_G_Push_P1' => 'Una vendita POS {not} arriva a Shopify da sola. Se l\'opzione è disattivata, il negozio lo scopre solo al successivo passaggio di invio dell\'inventario — e in quell\'intervallo può vendere un\'unità già venduta alla cassa.',
'Shp_G_Not' => 'non',
'Shp_G_Push_P2' => 'Spunti {setting} in {path}. È tutta qui la configurazione — nessun worker, nessun cron. Ogni vendita, reso e rettifica invia poi la giacenza dei soli prodotti interessati, subito dopo il salvataggio della vendita, e una vendita di venti righe costa un solo invio, non venti. La cassa non lo attende mai.',
'Shp_G_This_Store' => 'Questo negozio:',
'Shp_G_Push_On' => 'attivo — giacenza inviata a ogni variazione',
'Shp_G_Push_Off' => 'disattivo — giacenza solo secondo la pianificazione',
'Shp_G_Push_Note' => 'Vengono inviati solo i prodotti che hanno già una mappatura Shopify e solo i movimenti nel magazzino di questo negozio. Le operazioni massive — l\'eliminazione di un prodotto, l\'azzeramento di un magazzino — scrivono la giacenza senza generare un evento, il che è un motivo per mantenere anche il passaggio pianificato dell\'inventario.',
'Shp_G_Nothing_Else' => 'Nient\'altro da installare',
'Shp_G_Nothing_Else_Body' => 'Nessuna delle due metà richiede un worker di coda o una voce cron. Un webhook in entrata viene gestito nella richiesta effettuata da Shopify; un invio di giacenza in uscita viene eseguito nello stesso processo che ha servito la vendita, {after} che la risposta è stata restituita — così la cassa non attende mai Shopify, e un negozio che smette di rispondere viene abbandonato dopo dieci secondi e lasciato al successivo invio pianificato dell\'inventario.',
'Shp_G_After' => 'dopo',
'Shp_G_Exception' => 'Un\'eccezione: una variazione di giacenza effettuata da un\'attività in background non ha una risposta dopo cui partire, quindi viene messa in coda su {queue}.',
'Shp_G_Queue_Managed' => 'La sua piattaforma esegue già un worker su quella coda, quindi anche quegli invii partono da soli.',
'Shp_G_Queue_Cron' => 'Se vuole che anche questi partano tempestivamente, svuoti quella coda:',
'Shp_G_On_Schedule' => 'Secondo una pianificazione',
'Shp_G_On_Lc' => 'attivo',
'Shp_G_Off_Lc' => 'disattivo',
'Shp_G_Scheduled_Lead' => 'Tutto viene ricontrollato periodicamente, in entrambe le direzioni. È più lento del tempo reale, ma è ciò che invia la giacenza nei negozi che non usano l\'invio istantaneo, che recupera un webhook perso ed è l\'unico modo per spostare un intero catalogo.',
'Shp_G_Nothing_To_Install' => 'Nulla da installare',
'Shp_G_Managed_Body' => 'Il pianificatore viene eseguito per lei: ogni cinque minuti la sua piattaforma chiede a ogni negozio se è in scadenza un passaggio del suo piano ed esegue quelli che lo sono. Non c\'è alcuna voce cron da aggiungere né alcun server da gestire.',
'Shp_G_Managed_Note' => 'Cinque minuti è anche la granularità minima che un piano può usare, perché cinque minuti è l\'intervallo più breve per un passaggio. Gli intervalli più lunghi vengono rispettati esattamente — un passaggio impostato su 30 minuti viene controllato sei volte ed eseguito una volta.',
'Shp_G_Cron_Entry' => 'La voce cron',
'Shp_G_Cron_Body' => 'Senza di essa non viene eseguito nulla di pianificato. Una sola riga, solo per questo modulo — la aggiunga accanto a qualsiasi altra attività abbia scelto di pianificare:',
'Shp_G_Cron_Note' => 'Ogni cinque minuti è la granularità minima che un piano può usare, perché cinque minuti è l\'intervallo più breve per un passaggio. Una voce meno frequente diventa semplicemente il limite minimo — con {every15}, un passaggio impostato su 5 minuti viene eseguito ogni 15. Su Windows usi l\'Utilità di pianificazione: programma {php}, argomenti {args}, avvio in {path}.',
'Shp_G_Switch_On' => 'La attivi e scelga il piano',
'Shp_G_Plan_Body' => '{path} L\'interruttore decide se il pianificatore può agire; il piano decide cosa fa. Un {step} è un\'entità in una direzione con un proprio intervallo — {ex1}, {ex2}. L\'intervallo predefinito viene usato da ogni passaggio che lascia vuoto il proprio campo.',
'Shp_G_Step_Lc' => 'passaggio',
'Shp_G_Ex1' => 'Ordini · Shopify → ERP ogni 15 min',
'Shp_G_Ex2' => 'Inventario · ERP → Shopify ogni 30 min',
'Shp_G_Plan_Note' => 'Se lascia vuoto il piano, il negozio recupera gli ordini e invia la giacenza all\'intervallo predefinito, che è ciò che vuole la maggior parte dei negozi. Gli ordini sono solo in recupero: è su Shopify che un cliente effettua un ordine.',
'Shp_G_Schedule_On' => 'pianificazione attiva',
'Shp_G_Schedule_Off' => 'pianificazione disattiva — solo manuale',
'Shp_G_When_Runs' => 'Quando viene effettivamente eseguito un passaggio',
'Shp_G_When_Body' => 'Un passaggio è da eseguire quando lo stesso passaggio è stato {started} l\'ultima volta da più tempo del suo intervallo, secondo la cronologia delle esecuzioni. Quindi una sincronizzazione avviata manualmente posticipa la successiva automatica, e un passaggio che continua a non riuscire viene ritentato secondo il suo intervallo anziché a ogni controllo. La Panoramica del negozio mostra per ogni passaggio l\'ultima esecuzione, la prossima scadenza e, se è bloccato, il motivo. Esegua il primo invio del catalogo manualmente dal Centro di sincronizzazione — prima come simulazione — prima di pianificarlo.',
'Shp_G_Started_Lc' => 'avviato',
'Shp_G_Where_Setting' => 'Dove si trova ogni impostazione',
'Shp_G_Where_Note' => 'Tutte queste impostazioni si trovano su un negozio esistente: {path}, quindi la matita (oppure {edit} nella pagina del negozio).',
'Shp_G_Product_Images' => 'Immagini dei prodotti',
'Shp_G_Img1' => 'Le immagini vengono inviate insieme al prodotto durante un {push} — prima l\'immagine principale, poi la galleria, poi una per ogni variante che ne ha una propria, fino a cinquanta.',
'Shp_G_Products_Push' => 'invio dei prodotti',
'Shp_G_Img2' => 'L\'immagine di una variante viene caricata con il prodotto e poi {assigned}, che è il modello usato da Shopify: una variante punta a una delle immagini del prodotto. Una variante che riutilizza l\'immagine principale non la carica due volte.',
'Shp_G_Assigned' => 'assegnata a quella variante',
'Shp_G_Img3' => 'Un\'immagine memorizzata come file viene {uploaded} su Shopify, non collegata, quindi funziona anche quando questa installazione non è raggiungibile da Internet. Un\'immagine aggiunta come link incollato viene passata a Shopify come URL, che deve essere pubblicamente raggiungibile.',
'Shp_G_Uploaded' => 'caricata',
'Shp_G_Img4' => 'Vengono reinviate solo quando cambiano effettivamente — un invio che modifica solo un prezzo lascia invariate le immagini del negozio, perché inviarle sostituisce l\'intero set.',
'Shp_G_Img5' => 'Rimuovere un\'immagine nell\'ERP {not} la elimina in Shopify. La elimini anche lì, altrimenti il negozio continua a mostrarla.',
'Shp_G_Commands' => 'Comandi utili',
'Shp_G_Command_Copied' => 'Comando copiato',
'Shp_G_Foot' => 'Ogni sincronizzazione scrive in {logs} e la Panoramica di ogni negozio mostra quando ogni passaggio è stato eseguito l\'ultima volta, quando è la prossima scadenza e cosa lo blocca quando qualcosa non va. È il primo posto da controllare quando una sincronizzazione non ha fatto ciò che si aspettava.',
'Shp_G_Covers' => 'Copre',
'Shp_G_Speed' => 'Velocità',
'Shp_G_Needs' => 'Richiede',
'Shp_G_Switched_On_At' => 'Si attiva in',
'Shp_G_Way_Covers_Rt' => 'Ordini e modifiche effettuati in Shopify; giacenza in uscita dall\'ERP (una vendita POS, un reso, una rettifica)',
'Shp_G_Way_Covers_Sc' => 'Tutto, in entrambe le direzioni — compresi gli invii del catalogo e tutto ciò che il percorso rapido ha perso',
'Shp_G_Seconds' => 'Secondi',
'Shp_G_Way_Speed_Sc' => 'L\'intervallo del passaggio (da 5 minuti a 7 giorni)',
'Shp_G_Way_Needs_Rt' => 'Un indirizzo HTTPS pubblico e il segreto di firma per i webhook in entrata. La giacenza in uscita non richiede nulla',
'Shp_G_Way_Needs_Sc' => 'Il pianificatore, ogni cinque minuti',
'Shp_G_Way_Switch_Sc' => '{path}, più il piano',
'Shp_G_Scope_Orders' => '{a} ({b} per gli ordini più vecchi di 60 giorni)',
'Shp_G_Admin_Scopes' => 'Scope Admin API',
'Shp_G_Setting' => 'Impostazione',
'Shp_G_Tab_In_Edit' => 'Scheda in Modifica negozio',
'Shp_G_Set1' => 'Client ID + secret o token di accesso, segreto di firma, versione API',
'Shp_G_What1' => 'Le credenziali dell\'app Shopify (Dev Dashboard o app personalizzata legacy).',
'Shp_G_Set2' => 'Magazzino ERP, sede Shopify',
'Shp_G_What2' => 'Quale giacenza vende questo negozio e dove vengono registrati gli ordini.',
'Shp_G_What3' => 'Prezzo al dettaglio, all\'ingrosso o minimo.',
'Shp_G_Set4' => 'Crea prodotti / clienti mancanti',
'Shp_G_What4' => 'Se un recupero può creare record ERP che non riesce ad associare.',
'Shp_G_Set5' => 'Quali entità vengono sincronizzate',
'Shp_G_What5' => 'Disattivato qui significa disattivato ovunque — manuale, pianificato e webhook.',
'Shp_G_What6' => 'L\'interruttore del pianificatore.',
'Shp_G_What7' => 'Invio istantaneo della giacenza, messo in coda a ogni vendita o rettifica.',
'Shp_G_Set8' => 'Intervallo predefinito e piano dei passaggi',
'Shp_G_What8' => 'Cosa viene eseguito automaticamente, in quale direzione e con quale frequenza.',
'Shp_G_Cmd1' => 'Tutti i negozi: cosa verrebbe eseguito e quando. Non modifica nulla.',
'Shp_G_Cmd2' => 'L\'intero piano di un negozio, subito, ignorando l\'orario.',
'Shp_G_Cmd3' => 'Primo invio del catalogo: solo i prodotti non ancora collegati.',
'Shp_G_Cmd4' => 'Recupera gli ordini pregressi a partire da una data.',
