'Agt_Series' => 'Serie',
'Agt_Series_Hint' => 'L\'AGT autorizza una serie di numerazione per tipo di documento, anno e stabilimento. Non è possibile emettere fatture senza una serie attiva per il loro tipo e anno.',
'Agt_Request_Series' => 'Richiedi serie all\'AGT',
'Agt_Add_Series' => 'Aggiungi serie esistente',
'Agt_Contingency' => 'Contingenza',
'Normal' => 'Normale',
'Agt_Corrects' => 'Corregge',
'Agt_Late' => '> 24h',
'Agt_Check' => 'Verifica',
'Agt_Correct_Confirm' => 'Emettere una correzione con un nuovo numero per questo documento rifiutato?',
'Agt_Correct' => 'Correggi',
'Agt_Guide_What_Title' => 'Cosa fa',
'Agt_Guide_What_Body' => 'Ogni vendita completata viene emessa come fattura elettronica AGT (FR se pagata alla creazione, altrimenti FT) e ogni reso ricevuto come nota di credito (NC). Ogni documento riceve il numero successivo della sua serie AGT, viene firmato con la Sua chiave AGT e inviato all\'AGT, che lo convalida qualche minuto dopo. Lo scontrino e la fattura PDF riportano il numero AGT, l\'estratto di sicurezza e un codice QR.',
'Agt_Guide_Steps_Title' => 'Configurazione',
'Agt_Guide_Step_1' => 'Aderisca alla fatturazione elettronica (adesão) sul Portal do Contribuinte e scarichi la Sua chiave privata AGT.',
'Agt_Guide_Step_2' => 'Inserisca il NIF, lo stabilimento e la chiave nella scheda Configurazione, scelga Homologação, salvi e usi Testa la connessione.',
'Agt_Guide_Step_3' => 'Nella scheda Serie, richieda una serie per ogni tipo di documento che utilizza (FR, FT, NC) per l\'anno in corso.',
'Agt_Guide_Step_4' => 'Associ le Sue aliquote IVA ai codici AGT e imposti il codice di esenzione per le righe allo 0%.',
'Agt_Guide_Step_5' => 'Attivi il modulo in Impostazioni di sistema > Funzionalità, effettui una vendita di prova e verifichi che diventi valida nella scheda Documenti.',
'Agt_Guide_Step_6' => 'Quando l\'AGT La approva per la produzione, passi a Produção e richieda le serie di produzione.',
'Agt_Guide_Note_1' => 'Una vendita o un reso comunicato non può più essere modificato o eliminato. Lo corregga con un reso di vendita (nota di credito).',
'Agt_Guide_Note_2' => 'I documenti rifiutati dall\'AGT vengono corretti con un nuovo numero che fa riferimento a quello rifiutato; il vecchio numero non viene mai riutilizzato.',
'Agt_Guide_Note_3' => 'Le vendite POS offline vengono comunicate al momento della sincronizzazione. L\'AGT sanziona i documenti inviati con più di 24 ore di ritardo.',
'Agt_Guide_Note_4' => 'Una riga non può avere sia un\'imposta di prodotto sia l\'imposta dell\'ordine; l\'AGT richiede una sola aliquota IVA per riga. La spedizione viene inviata come riga esente.',
'Agt_Guide_Note_5' => 'I totali AGT sono calcolati per riga e possono differire dal totale di Stocky di qualche centesimo per arrotondamento.',
