'Dgi_Api_Pending_Body' => 'La DGI pubblica l\'API per sviluppatori e-MCF solo per gli sviluppatori registrati (developper.dgirdc.cd). Finché non è collegata, le fatture riportano le Sue diciture NIF / RCCM / Id. Nat. ma nessun numero DEF, codice di autenticazione o QR.',
