'Dgi_No_Documents' => 'Nessuna fattura certificata finora — la certificazione inizia una volta attiva la connessione e-MCF.',
'Dgi_Guide_What_Title' => 'Cosa fa oggi',
'Dgi_Guide_What_Body' => 'Con il modulo attivo, gli scontrini e le fatture PDF riportano NIF, RCCM e Id. Nat. del venditore, richiesti sulla facture normalisée. La certificazione completa (numero DEF, contatori, codice di autenticazione e QR restituiti dalla DGI) viene aggiunta una volta collegata l\'API per sviluppatori e-MCF.',
'Dgi_Guide_Steps_Title' => 'Ottenere l\'accesso all\'e-MCF',
'Dgi_Guide_Step_1' => 'Crei un account con il Suo NIF su developper.dgirdc.cd e richieda l\'accesso all\'ambiente di test e-MCF.',
'Dgi_Guide_Step_2' => 'Scarichi la documentazione API (route, DTO, gruppi di tassazione) e le credenziali di test.',
