'VG_List_Title' => 'Modalità elenco semplice',
'VG_List_Text' => 'Digiti il nome di una variante e prema Invio (o faccia clic su Aggiungi) per aggiungere una riga, poi compili codice e prezzi. È il comportamento classico e resta disponibile per i prodotti esistenti.',
'VG_Edit_Title' => 'Modifiche successive',
