'Comm_G_Flow_Pay_Help' => 'Registri una Ricevuta di commissione per l\'agente. Le commissioni che copre diventano Pagate.',
'Comm_G_How_It_Works' => 'Come funziona',
'Comm_G_T_Credit' => 'Quale agente riceve la commissione?',
'Comm_G_Credit_Intro' => 'Ogni vendita viene attribuita al massimo a un agente. Il sistema verifica, in questo ordine:',
'Comm_G_Credit_Picked' => 'L\'agente di vendita scelto sulla vendita: il campo Agente di vendita in Aggiungi vendita e Modifica vendita, oppure il pulsante "Venduto da" sul POS. Se nel frattempo quell\'agente è stato disattivato, la vendita non matura nulla; non si passa alle opzioni successive.',
'Comm_G_Credit_Seller' => 'Altrimenti, l\'agente collegato al venditore scelto sul POS (quando l\'opzione venditore del POS è attiva).',
'Comm_G_Credit_Cashier' => 'Altrimenti, l\'agente collegato all\'utente che ha salvato la vendita.',
'Comm_G_Credit_Nobody' => 'Se nessuna di queste trova un agente attivo, la vendita non matura alcuna commissione.',
'Comm_G_Credit_Note' => 'Sul POS, lasciando l\'agente su "Automatico" si usano le opzioni 2 e 3. Il nome mostrato accanto ad "Automatico" è l\'agente a cui verrà attribuita la vendita.',
'Comm_G_T_When' => 'Quando vengono calcolate e aggiornate le commissioni?',
'Comm_G_When_Intro' => 'Le commissioni vengono create la prima volta quando viene salvata una vendita con stato Completata, in uno di questi punti:',
'Comm_G_When_Create' => 'Aggiungi vendita: quando la vendita viene salvata come Completata.',
'Comm_G_When_Edit' => 'Modifica vendita: salvare una vendita Completata la ricalcola da zero con totale, pagamenti e agente attuali, incluse le commissioni che erano state annullate.',
'Comm_G_When_Pos' => 'POS: quando una vendita viene completata, inclusa una bozza completata in seguito.',
'Comm_G_When_Payment' => 'Aggiunta di un pagamento a una vendita Completata: è ciò che consente alle regole su Importo pagato di includere i pagamenti incassati dopo la vendita.',
'Comm_G_When_Cod' => 'Contrassegno tramite corriere: quando il contante incassato dal corriere viene registrato come pagamento della vendita.',
'Comm_G_When_Not_Intro' => 'Questi casi NON creano commissioni:',
'Comm_G_When_Not_Status' => 'Vendite salvate come In sospeso o Ordinata. Iniziano a maturare commissioni quando vengono modificate e salvate come Completata.',
'Comm_G_When_Not_Before' => 'Vendite salvate prima dell\'esistenza del programma o della regola. Non vengono calcolate in background. Aprendo una di queste vendite in Modifica vendita e salvandola, viene calcolata con le regole attive alla data della vendita.',
'Comm_G_When_Not_Import' => 'Vendite importate da un file.',
'Comm_G_When_Not_Online' => 'Ordini effettuati nel negozio online.',
'Comm_G_T_Statuses' => 'Stati delle commissioni',
'Comm_G_Meaning' => 'Significato',
'Comm_G_S_Pending' => 'Appena calcolata da una vendita. Nessuno l\'ha ancora verificata. La approvi o la annulli nel Report commissioni.',
'Comm_G_S_Approved' => 'Verificata e accettata. È dovuta all\'agente e può essere inclusa in una Ricevuta di commissione. Se la vendita cambia e l\'importo varia, torna In sospeso per un\'ulteriore verifica.',
'Comm_G_S_Paid' => 'Inclusa in una Ricevuta di commissione. Definitiva: le commissioni pagate non vengono mai modificate. Se in seguito la vendita cambia, la differenza viene aggiunta come Rettifica separata.',
'Comm_G_S_Cancelled' => 'Non verrà pagata. Resta annullata anche se in seguito arrivano pagamenti o resi. Salvando la vendita in Modifica vendita, oppure spuntandola nel report e facendo clic su Ricalcola, viene calcolata di nuovo.',
'Comm_G_Field' => 'Campo',
'Comm_G_T_Programs' => 'Programmi di commissione',
'Comm_G_Programs_Body' => 'Un programma è un contenitore di regole, di solito uno per periodo o campagna. Una regola funziona solo finché il suo programma è Attivo e la data della vendita rientra nelle date del programma. Più programmi possono essere attivi contemporaneamente e si applicano tutti.',
'Comm_G_F_Program_Name' => 'Qualsiasi nome che La aiuti a riconoscere il programma, ad esempio "Q4 2026" o "Black Friday".',
'Comm_G_F_Program_Active' => 'Tolga la spunta per sospendere in un colpo solo tutte le regole del programma. Le commissioni già create non vengono modificate.',
'Comm_G_F_Program_From' => 'Le vendite con data precedente a questo giorno vengono ignorate dal programma. Lasci vuoto per nessuna data di inizio.',
'Comm_G_F_Program_To' => 'Le vendite con data successiva a questo giorno vengono ignorate dal programma. Lasci vuoto per un programma senza scadenza.',
'Comm_G_T_Agents' => 'Agenti di vendita',
'Comm_G_Agents_Body' => 'Un agente di vendita è la persona che matura la commissione. Un agente non deve per forza essere un utente del sistema: anche segnalatori o rivenditori esterni possono essere agenti e maturano commissioni ogni volta che vengono scelti su una vendita.',
'Comm_G_F_Agent_Name' => 'Il nome mostrato su vendite, report e ricevute.',
'Comm_G_F_Agent_Code' => 'Riferimento facoltativo, ad esempio un numero di matricola. Ricercabile nell\'elenco degli agenti.',
'Comm_G_F_Agent_User' => 'Collega l\'agente a un utente del personale. Le vendite effettuate da quell\'utente (o per cui è scelto come venditore sul POS) vengono quindi attribuite automaticamente a questo agente.',
'Comm_G_F_Agent_Active' => 'Gli agenti inattivi non maturano nulla sulle nuove vendite e scompaiono dai selettori degli agenti. Le loro commissioni passate restano.',
'Comm_G_T_Rules' => 'Regole di commissione: ogni campo spiegato',
'Comm_G_Rules_Body' => 'Una regola decide quanto viene pagato su una vendita. Usi il riquadro "Provi una regola" qui sopra per verificare una regola prima di salvarla.',
'Comm_G_F_Rule_Program' => 'Il programma a cui appartiene la regola. La regola funziona solo finché quel programma è attivo e nelle date di validità.',
'Comm_G_F_Rule_Type' => 'Percentuale paga una quota dell\'importo base. Fisso paga lo stesso importo su ogni vendita idonea, qualunque sia il suo importo.',
'Comm_G_F_Rule_Source' => 'Ciò da cui viene calcolata la percentuale. Totale vendita è il totale complessivo della vendita. Importo pagato è quanto il cliente aveva pagato al momento del calcolo della commissione.',
'Comm_G_F_Rule_Value' => 'La percentuale (5 significa 5%) o l\'importo fisso, a seconda del Tipo.',
'Comm_G_F_Rule_Min' => 'Facoltativo. Le vendite il cui importo base è inferiore a questo valore non maturano nulla da questa regola. Una vendita esattamente pari alla soglia matura la commissione.',
'Comm_G_F_Rule_Cap' => 'Facoltativo. L\'importo massimo che questa regola può pagare su una vendita. Vale sia per le regole a percentuale sia per quelle fisse.',
'Comm_G_F_Rule_Applies' => 'Tutti gli agenti: ogni agente matura commissioni da questa regola. Agente specifico: solo l\'agente selezionato. Una regola Agente specifico senza agente selezionato non paga mai nessuno.',
'Comm_G_F_Rule_Priority' => 'In un programma impostato su "Paga solo la regola con priorità più alta", vince la regola idonea con il numero più alto e le altre vengono saltate. A parità, una regola Agente specifico prevale su una regola Tutti gli agenti. In un programma impostato su "Paga ogni regola corrispondente", la Priorità stabilisce solo l\'ordine.',
'Comm_G_F_Rule_Active' => 'Tolga la spunta per sospendere solo questa regola. Le commissioni già create non vengono modificate.',
'Comm_G_T_Stacking' => 'Più regole su una vendita',
'Comm_G_Stacking_Body' => 'Ogni programma decide come si combinano le sue regole (l\'impostazione "Quando più regole corrispondono" del programma).

Paga solo la regola con priorità più alta (l\'impostazione predefinita per i nuovi programmi): le regole vengono provate dalla Priorità più alta in giù e paga la prima idonea per la vendita. Una regola è idonea quando la vendita raggiunge la sua soglia minima e il risultato è superiore a 0. Questo rende semplici gli scaglioni: "7% sulle vendite da 10,000 in su" con priorità 10 e "5%" con priorità 0. Per dare a Sara una percentuale speciale, aggiunga per lei una regola Agente specifico con priorità più alta della regola Tutti gli agenti.

Paga ogni regola corrispondente: tutte le regole corrispondenti pagano e gli importi si sommano. Una regola Tutti gli agenti del 3% più una regola Agente specifico del 2% per Sara dà a Sara il 5%.

I programmi sono indipendenti tra loro: ogni programma attivo paga per conto proprio, quindi una vendita può maturare commissioni da un programma base e da un programma di campagna contemporaneamente.',
'Comm_G_T_Paying' => 'Pagare gli agenti con le Ricevute di commissione',
'Comm_G_Paying_Body' => 'Apra Ricevute di commissione e faccia clic su Aggiungi. Scelga l\'agente: vengono elencate le sue commissioni Approvate. Spunti quelle che sta pagando; l\'Importo si compila con il loro totale e può modificarlo. Il Rif. viene compilato automaticamente (CR-000001, CR-000002...) e può aggiungere il metodo di pagamento, la data e una nota.

Il salvataggio della ricevuta segna le commissioni spuntate come Pagate e le collega alla ricevuta. Possono essere pagate solo le commissioni Approvate, quindi le approvi prima nel Report commissioni.

Vengono elencate anche le Rettifiche negative (denaro pagato in eccesso all\'agente). Le spunti insieme alle commissioni successive dell\'agente, così vengono detratte da quel pagamento.

Una ricevuta registra solo l\'erogazione: non crea una spesa né sposta denaro nei Suoi conti. Se tiene traccia delle erogazioni in Spese o Contabilità, le registri anche lì.',
'Comm_G_T_Snapshot' => 'Quando una vendita cambia',
'Comm_G_Snapshot_Body' => 'Le commissioni seguono la vendita. Ogni volta che una vendita con commissioni cambia, queste vengono ricalcolate in base ai suoi dati attuali: il totale della vendita meno i resi ricevuti e l\'importo pagato meno i rimborsi.

Le commissioni non pagate (In sospeso o Approvate) vengono semplicemente aggiornate. Una commissione Approvata il cui importo cambia torna In sospeso affinché qualcuno la verifichi di nuovo. Una commissione non più dovuta (vendita eliminata, interamente resa, agente cambiato) viene rimossa.

Le commissioni pagate non vengono mai modificate. La differenza diventa una nuova riga In sospeso contrassegnata come Rettifica: positiva quando è dovuto di più (ad esempio è stato pagato il resto di una vendita con regola su Importo pagato), negativa quando l\'agente è stato pagato in eccesso (ad esempio dopo un reso). La approvi e la includa nella successiva ricevuta dell\'agente.

Ogni commissione mantiene le condizioni della regola (tipo, percentuale, soglia, tetto) del momento in cui è stata maturata. Modificare o disattivare una regola in seguito non ricalcola il prezzo delle vendite precedenti quando vengono ricalcolate.',
'Comm_G_T_Permissions' => 'Chi può fare cosa',
'Comm_G_Permission' => 'Permesso',
'Comm_G_Lets_You' => 'Cosa consente',
'Comm_G_P_View' => 'Vedere tutte le pagine Commissioni: programmi, agenti, regole, ricevute, il report e questa guida.',
'Comm_G_P_Add' => 'Creare programmi, agenti e regole e registrare Ricevute di commissione (pagare gli agenti).',
'Comm_G_P_Edit' => 'Modificare programmi, agenti e regole e approvare o annullare commissioni nel Report commissioni.',
'Comm_G_P_Delete' => 'Eliminare programmi, agenti e regole.',
'Comm_G_T_Faq' => 'Domande e risposte',
'Comm_G_Q_Empty' => 'Ho configurato tutto, ma il Report commissioni è vuoto.',
'Comm_G_A_Empty' => 'Verifichi che: la vendita sia stata salvata dopo la creazione della regola; la vendita sia Completata; la vendita abbia un agente (scelto sulla vendita, oppure l\'utente che l\'ha effettuata è collegato a un agente); il programma sia attivo e la data della vendita rientri nelle sue date; la regola sia attiva e si applichi a quell\'agente; e la vendita sia pari o superiore alla soglia minima della regola. Controlli anche il filtro per data del report: filtra in base alla data in cui è stata calcolata la commissione.',
'Comm_G_Q_Twice' => 'Un agente ha ricevuto due commissioni su una vendita.',
'Comm_G_A_Twice' => 'Hanno pagato due regole: o il programma è impostato su "Paga ogni regola corrispondente", oppure le regole sono in due diversi programmi attivi (ogni programma paga per conto proprio). Imposti il programma su "Paga solo la regola con priorità più alta" se deve pagarne una sola. Salvare di nuovo una vendita non duplica mai una commissione.',
'Comm_G_Q_Rate' => 'Se modifico la percentuale di una regola, le vecchie commissioni cambiano?',
'Comm_G_A_Rate' => 'No. Ogni commissione mantiene le condizioni della regola con cui è stata maturata, anche quando la vendita viene ricalcolata in seguito. La nuova percentuale si applica alle commissioni maturate da ora in poi.',
'Comm_G_Q_Return' => 'Il cliente ha reso la merce. Cosa succede alla commissione?',
'Comm_G_A_Return' => 'Viene ridotta automaticamente. Un reso ricevuto riduce il totale della vendita e un rimborso riduce l\'importo pagato. Se la commissione non era ancora stata pagata, viene aggiornata (o rimossa in caso di reso totale). Se era già stata pagata, viene aggiunta una Rettifica negativa che viene detratta dalla successiva ricevuta dell\'agente.',
'Comm_G_Q_Wrong_Agent' => 'Ho attribuito la vendita all\'agente sbagliato. Come posso correggere?',
'Comm_G_A_Wrong_Agent' => 'Modifichi la vendita, scelga l\'Agente di vendita corretto e salvi. Le commissioni passano all\'agente corretto. Se il primo agente era già stato pagato, per lui viene aggiunta una Rettifica negativa.',
'Comm_G_Q_Inactive' => 'Cosa succede quando disattivo un agente?',
'Comm_G_A_Inactive' => 'Smette di maturare commissioni sulle nuove vendite e viene nascosto dai selettori degli agenti. Le sue commissioni esistenti restano, possono ancora essere approvate e pagate e continuano a seguire le modifiche alle relative vendite. Una vendita salvata con quell\'agente scelto non passerà a un altro agente.',
'Comm_G_Q_Partial' => 'Come gestiscono i pagamenti parziali le regole su Importo pagato?',
'Comm_G_A_Partial' => 'Una vendita non pagata non matura nulla. La commissione viene creata quando si riceve il primo incasso (al checkout o quando viene aggiunto un pagamento) e cresce man mano che arrivano altri pagamenti. Se una parte era già stata pagata, il resto arriva come Rettifica positiva.',
'Comm_G_Q_Undo' => 'Posso annullare un pagamento o un annullamento?',
'Comm_G_A_Undo' => 'Un pagamento, no: Pagato è definitivo e le ricevute non possono essere modificate né eliminate, quindi controlli le commissioni spuntate e l\'importo prima di salvare. Un annullamento, sì: spunti la riga nel Report commissioni e faccia clic su Ricalcola, oppure salvi di nuovo la vendita in Modifica vendita.',
'Comm_G_Q_Dates' => 'Quale data usano le date del programma?',
'Comm_G_A_Dates' => 'La data della vendita stessa, non il giorno in cui è stata salvata. Una vendita datata il mese scorso usa solo i programmi validi il mese scorso.',
'Comm_G_When_Changes' => 'Successivamente, qualsiasi modifica a una vendita che ha già commissioni le aggiorna automaticamente: pagamenti modificati o eliminati, resi e rimborsi, lo stato che non è più Completata o l\'eliminazione della vendita.',
'Comm_G_F_Program_Mode' => 'Cosa succede quando più regole di questo programma corrispondono alla stessa vendita. "Paga solo la regola con priorità più alta": le regole vengono provate dalla Priorità più alta in giù e paga la prima idonea. "Paga ogni regola corrispondente": pagano tutte e gli importi si sommano.',
'Comm_G_Q_Mode_Old' => 'Ho impostato le priorità, ma le regole si sommano ancora.',
'Comm_G_A_Mode_Old' => 'Quel programma è impostato su "Paga ogni regola corrispondente". I programmi creati prima dell\'esistenza di questa impostazione mantengono quel comportamento, così le loro erogazioni non cambiano. Modifichi il programma e scelga "Paga solo la regola con priorità più alta".',
'Comm_G_Q_Negative' => 'Perché c\'è una commissione negativa?',
'Comm_G_A_Negative' => 'È una Rettifica: all\'agente è stato pagato più di quanto la vendita frutti ora, a causa di un reso, un rimborso, un totale inferiore, un cambio di agente o una vendita eliminata. La approvi e la spunti nella successiva ricevuta dell\'agente affinché venga detratta.',
'Comm_Rule_Mode' => 'Quando più regole corrispondono',
'Comm_Mode_Highest' => 'Paga solo la regola con priorità più alta',
'Comm_Mode_All' => 'Paga ogni regola corrispondente (si sommano)',
'Comm_Mode_Highest_Short' => 'Vince la priorità più alta',
'Comm_Mode_All_Short' => 'Le regole si sommano',
'Comm_Mode_Highest_Help' => 'Le regole vengono provate dalla Priorità più alta in giù; paga la prima idonea per la vendita e le altre vengono saltate. Adatto agli scaglioni, ad esempio 7% oltre 10,000 con priorità 10 e 5% per tutto il resto con priorità 0.',
'Comm_Mode_All_Help' => 'Ogni regola corrispondente all\'agente paga sulla vendita, quindi gli importi si sommano. La Priorità stabilisce solo l\'ordine.',
'Comm_Priority_Help_Highest' => 'Questo programma paga solo la regola idonea con priorità più alta. Assegni a questa regola una Priorità più alta delle regole su cui deve prevalere. A parità, una regola Agente specifico prevale su una regola Tutti gli agenti.',
'Comm_Priority_Help_All' => 'Questo programma paga ogni regola corrispondente, quindi questa regola si somma alle altre. La Priorità stabilisce solo l\'ordine.',
'Comm_Recalculate' => 'Ricalcola',
'Comm_Recalculate_Help' => 'Ricalcola le vendite delle righe spuntate in base ai loro dati attuali, incluse le commissioni annullate.',
'Comm_Adjustment' => 'Rettifica',
'Comm_Adjustment_Help' => 'Una correzione a una commissione già pagata, perché in seguito la vendita è cambiata. Un importo negativo viene detratto dalla successiva ricevuta dell\'agente.',
'Comm_Cancel_Confirm' => 'Annullare le commissioni selezionate?',
'Comm_Cancel_Confirm_Help' => 'Non verranno pagate e resteranno annullate anche se in seguito arrivano pagamenti o resi. Salvando la vendita in Modifica vendita o facendo clic su Ricalcola vengono calcolate di nuovo.',
'Fashion_Tiles_Hint' => 'Aggiunga i propri riquadri (immagine, titolo e link) per sostituire i riquadri automatici delle categorie.',

