'Cars_Reserve_Product' => 'Prodotto acconto',
'Cars_Reserve_Product_Hint' => 'Crei un prodotto di tipo servizio chiamato ad esempio "Acconto prenotazione" con l\'importo dell\'acconto come prezzo, poi lo scelga qui. Riservare un\'auto registra un lead e inserisce questo prodotto nel carrello. Non viene mai elencato nel catalogo veicoli.',
