'Rst_Guide_Service_4' => 'Il display di cucina mostra la comanda in ogni postazione. I cuochi la avviano, spuntano i piatti man mano che li completano e la evadono quando tutto è pronto.',
'Rst_Guide_Service_5_T' => 'Servire',
'Rst_Guide_Service_5' => 'I piatti pronti compaiono sulla pianta della sala e nella schermata dell\'ordine. Il cameriere li porta in sala e tocca "Segna come serviti".',
'Rst_Guide_Service_6_T' => 'Conto',
'Rst_Guide_Service_6' => '"Conto e pagamento" stampa il conto e incassa il pagamento: conto intero, diviso in parti uguali o per piatto. Ogni pagamento è una normale vendita POS.',
'Rst_Guide_Service_7_T' => 'Liberare',
'Rst_Guide_Service_7' => 'Quando tutto è pagato l\'ordine si chiude e il tavolo passa a "Da pulire" (o direttamente a libero, secondo le Impostazioni ristorante).',
'Rst_Guide_Roles' => 'Chi fa cosa',
'Rst_Guide_Roles_Help' => 'Le autorizzazioni del ristorante si assegnano per ruolo in Autorizzazioni di gruppo. Un utente può cumulare le autorizzazioni di più ruoli.',
'Rst_Guide_Job' => 'Mansione',
'Rst_Guide_Give' => 'Assegnare queste autorizzazioni',
'Rst_Guide_Job_Waiter' => 'Cameriere',
'Rst_Guide_Job_Cook' => 'Cuoco',
'Rst_Guide_Job_Cashier' => 'Cassiere',
'Rst_Guide_Job_Host' => 'Accoglienza / reception',
'Rst_Guide_Job_Supervisor' => 'Supervisore',
'Rst_Guide_Job_Manager' => 'Responsabile',
'Rst_Guide_Menu' => 'Menu, postazioni e aggiunte',
'Rst_Guide_Menu_1' => 'Ogni prodotto venduto può essere un piatto. Ristorante › Menu (o la scheda "Dettagli del piatto" nel modulo del prodotto) aggiunge le informazioni per il ristorante.',
'Rst_Guide_Menu_2' => 'I gruppi di aggiunte contengono scelte con un prezzo: "Formato" (scegliere 1) o "Extra" (fino a 3). Le regole vengono verificate su ogni ordine, anche online.',
'Rst_Guide_Menu_3' => 'Un\'aggiunta può scaricare un ingrediente: colleghi "Formaggio extra" al prodotto Formaggio e ciascuna ne preleverà le scorte.',
'Rst_Guide_Menu_4' => 'Segni un piatto come esaurito per oggi con un solo interruttore; tornerà disponibile domani da solo. Gli orari dei pasti (colazione, pranzo, cena) limitano quando un piatto viene proposto.',
'Rst_Guide_Menu_5' => 'Una ricetta è un prodotto combinato: con le scorte virtuali dei prodotti combinati attive, la vendita del piatto preleva i componenti dalle scorte.',
'Rst_Guide_Kitchen' => 'Display di cucina',
'Rst_Guide_Kitchen_1' => 'Apra Ristorante › Cucina su uno schermo in cucina. Selezioni la postazione; i piatti senza postazione compaiono in tutte le postazioni.',
'Rst_Guide_Kitchen_2' => 'Le comande diventano gialle e poi rosse man mano che attendono (Impostazioni ristorante › in ritardo dopo N minuti). Un segnale acustico annuncia le nuove comande.',
'Rst_Guide_Kitchen_3' => 'Avvia → spunta i piatti → Evadi. "Completato in questa postazione" completa solo i piatti di questa postazione su una comanda condivisa.',
'Rst_Guide_Kitchen_4' => 'Le comande servite restano visibili 15 minuti per poter richiamare un errore. Le comande si possono stampare su una stampante da 80 mm.',
'Rst_Guide_Kitchen_5' => 'Gli ordini dal negozio online e dai codici QR dei tavoli sono contrassegnati come "Online" o "QR" sulla comanda.',
'Rst_Guide_Bills' => 'Conti e pagamenti',
'Rst_Guide_Bills_1' => 'Ogni pagamento è una normale vendita POS: scorte, cassa, contabilità, punti fedeltà e fatturazione elettronica funzionano come al POS.',
'Rst_Guide_Bills_2' => 'Il costo del servizio è una percentuale dei piatti al netto delle imposte, per gli ordini al tavolo (o per tutti gli ordini, secondo l\'impostazione). Le mance sono una percentuale predefinita o un importo.',
'Rst_Guide_Bills_3' => 'Uno sconto richiede l\'autorizzazione "Applicare sconti sui conti" ed è limitato dallo sconto massimo consentito nelle Impostazioni ristorante.',
'Rst_Guide_Bills_4' => 'L\'arrotondamento avviene per difetto al passo impostato, a favore dell\'ospite, sul pagamento che salda il conto.',
'Rst_Guide_Bills_5' => 'Divisione in parti uguali: una vendita, una riga di pagamento per persona (quote al centesimo). Divisione per piatto: i piatti di ogni ospite diventano una vendita separata; selezioni un posto per selezionarne i piatti.',
'Rst_Guide_Bills_6' => 'Se il conto è cambiato dopo essere stato mostrato (un piatto aggiunto da un codice QR, una mancia modificata), il pagamento viene rifiutato, così all\'ospite non viene mai addebitato qualcosa che non ha visto.',
'Rst_Guide_Bills_7' => 'I piatti pagati non possono essere stornati. Se la parte non pagata di un ordine viene stornata, l\'ordine si chiude come pagato e il tavolo può essere liberato.',
'Rst_Guide_Bookings' => 'Prenotazioni e lista d\'attesa',
'Rst_Guide_Bookings_1' => 'Le prenotazioni riservano un tavolo per la loro durata (valore predefinito nelle Impostazioni ristorante). Due prenotazioni non possono mai sovrapporsi sullo stesso tavolo.',
'Rst_Guide_Bookings_2' => 'La pianta della sala mostra la prossima prenotazione di ogni tavolo e avvisa quando è imminente; "Sono arrivati — fai accomodare" fa accomodare il gruppo.',
'Rst_Guide_Bookings_3' => 'Trascorso il tempo di no-show, un gruppo in ritardo può essere segnato come no-show; un errore può essere ripristinato.',
'Rst_Guide_Bookings_4' => 'La lista d\'attesa mantiene in ordine i clienti senza prenotazione con l\'attesa indicata. Li chiami o contatti su WhatsApp quando un tavolo è pronto, poi li faccia accomodare.',
'Rst_Guide_Bookings_5' => 'Le prenotazioni online arrivano come "Prenotata" (un badge nella barra laterale le conta) in attesa della Sua conferma.',
'Rst_Guide_Online' => 'Ordini online, menu QR e prenotazione online',
'Rst_Guide_Online_1' => 'Con il tema Ristorante del negozio, la homepage del negozio online è il Suo menu, con aggiunte e filtri alimentari; i clienti pagano al checkout come di consueto.',
'Rst_Guide_Online_2' => '"Gli ordini online vanno in cucina" decide quando arrivano sul display di cucina: all\'invio (pagati, o di un cliente registrato che paga alla consegna / al ritiro), all\'accettazione, o mai.',
'Rst_Guide_Online_3' => 'I codici QR dei tavoli (Configurazione sala › Codici QR dei tavoli) aprono il menu per quel tavolo. "Nuovo link" disattiva un codice stampato.',
'Rst_Guide_Online_4' => 'Gli ordini QR restano sull\'ordine del tavolo finché un cameriere non li invia, a meno che "Invia gli ordini QR direttamente in cucina" sia attivo. Gli ospiti pagano al personale.',
'Rst_Guide_Online_5' => 'La prenotazione online propone solo orari in cui un tavolo adatto al gruppo è libero per l\'intera prenotazione e limita ogni numero di telefono a 3 prenotazioni future.',
'Rst_Guide_Online_6' => 'Tutto questo fa parte del negozio online: deve essere attivato e incluso nel Suo piano.',
'Rst_Guide_Reports' => 'Dashboard e report',
'Rst_Guide_Reports_1' => 'La dashboard confronta oggi con lo stesso giorno della settimana scorsa: vendite, conti, ospiti, conto medio, storni e sconti, oltre a ciò che sta accadendo in questo momento.',
'Rst_Guide_Reports_2' => 'Le vendite sono i conti del ristorante più gli ordini online arrivati in cucina. Vendite e margini dei piatti sono al netto delle imposte e usano il costo di ciascun prodotto.',
'Rst_Guide_Reports_3' => 'Report: vendite per giorno e metodo di pagamento, piatti, storni e annullamenti (con i motivi), personale, tempi di cucina e prenotazioni — ciascuno esportabile in Excel.',
'Rst_Guide_Reports_4' => 'Il personale limitato ad alcune filiali vede solo le proprie filiali; gli ordini senza filiale sono condivisi da tutti.',
'Rst_Guide_Faq' => 'Buono a sapersi',
'Rst_Guide_Faq_1_Q' => 'Un asporto è stato pagato prima che premessi "Invia". Verrà preparato?',
'Rst_Guide_Faq_1_A' => 'Sì. Il pagamento invia in cucina tutti i piatti non ancora inviati.',
'Rst_Guide_Faq_2_Q' => 'Perché non riesco a liberare un tavolo?',
'Rst_Guide_Faq_2_A' => 'Il suo ordine contiene ancora piatti non pagati. Incassi il pagamento, storni ciò che non è stato consumato o annulli l\'ordine (solo se non è ancora stato pagato nulla).',
'Rst_Guide_Faq_3_Q' => 'Due tavoli sono stati accostati. Cosa succede ai loro ordini?',
'Rst_Guide_Faq_3_A' => '"Unisci tavoli" sposta i piatti del secondo tavolo (e gli eventuali pagamenti) sull\'ordine del tavolo principale; "Separa questo tavolo" divide di nuovo i tavoli.',
'Rst_Guide_Faq_4_Q' => 'I pagamenti con carta possono usare Stripe qui?',
'Rst_Guide_Faq_4_A' => 'No. I pagamenti con carta tramite Stripe richiedono il modulo carta del POS; per un terminale di pagamento aggiunga un metodo di pagamento come "Carta" e lo usi sul conto.',
'Rst_Guide_Faq_5_Q' => 'Un piatto è esaurito in una sola filiale.',
'Rst_Guide_Faq_5_A' => 'Le scorte vengono prelevate dalla filiale dell\'ordine (l\'area del tavolo, altrimenti la filiale predefinita nelle Impostazioni ristorante). Usi "Esaurito oggi" per bloccare rapidamente gli ordini.',
'Rst_Guide_Faq_6_Q' => 'Serve una stampante?',
'Rst_Guide_Faq_6_A' => 'No. Conti, scontrini e comande di cucina si stampano dal browser su qualsiasi stampante; le stampanti per scontrini da 80 mm sono le più adatte.',
'Rst_Guide_Faq_7_Q' => 'Da dove provengono i menu del ristorante nel negozio online?',
'Rst_Guide_Faq_7_A' => 'Dagli stessi prodotti, categorie e aggiunte. I prodotti nascosti dal negozio online e le categorie non mostrate nel negozio restano fuori dal menu online e dal menu QR.',

