'Bkm_Guide_Requests_2' => 'Conferma sceglie un operatore al posto Suo se lascia il campo vuoto e verifica che l\'orario sia ancora libero.',
'Bkm_Guide_Requests_3' => 'Proponga un altro orario quando quello del cliente non va bene: il cliente lo accetta dalla pagina della sua prenotazione.',
'Bkm_Guide_Requests_4' => 'Rifiuti indicando un motivo; il cliente lo vede.',
'Bkm_Guide_Requests_5' => 'Una riserva scaduta libera l\'orario; la prenotazione resta finché Lei non risponde.',
'Bkm_Guide_Day' => 'Il giorno dell\'appuntamento',
'Bkm_Guide_Day_1' => 'La Vista giornaliera mostra affiancate le prenotazioni di ciascun operatore.',
'Bkm_Guide_Day_2' => 'Segni come arrivato quando il cliente si presenta.',
'Bkm_Guide_Day_3' => 'Completa e addebita crea la vendita tramite il POS, con l\'acconto già conteggiato.',
'Bkm_Guide_Day_4' => 'Completi senza addebito quando il pagamento è avvenuto in altro modo.',
'Bkm_Guide_Day_5' => 'Segni come non presentato una volta passato l\'orario di inizio.',
'Bkm_Guide_Day_6' => 'La dashboard mostra il programma di oggi, ciò che deve ancora avvenire e ciò che non è ancora stato addebitato.',
'Bkm_Guide_Deposits' => 'Acconti',
'Bkm_Guide_Deposits_1' => 'Imposti l\'importo in Impostazioni prenotazioni › Acconto; un servizio può averne uno proprio.',
'Bkm_Guide_Deposits_2' => 'I clienti pagano con i fornitori di pagamenti configurati in Negozio online › Gateway di pagamento, nella Sua valuta di base.',
'Bkm_Guide_Deposits_3' => 'L\'orario resta riservato in attesa del pagamento; le prenotazioni non pagate possono essere annullate automaticamente.',
'Bkm_Guide_Deposits_4' => 'Un pagamento andato a buon fine senza che il cliente sia tornato sul sito viene rilevato automaticamente.',
'Bkm_Guide_Deposits_5' => 'Quando addebita la prenotazione, l\'acconto è il primo pagamento della vendita.',
'Bkm_Guide_Deposits_6' => 'I rimborsi si effettuano tramite il Suo fornitore di pagamenti; poi segni l\'acconto come rimborsato sulla prenotazione.',
'Bkm_Guide_Messages' => 'Email, WhatsApp e promemoria',
'Bkm_Guide_Messages_1' => 'I clienti ricevono un\'email quando la loro prenotazione viene ricevuta, confermata, rifiutata, modificata o annullata.',
'Bkm_Guide_Messages_2' => 'Lei ne riceve una per ogni nuova prenotazione dal sito web, annullamento da parte del cliente e acconto pagato.',
'Bkm_Guide_Messages_3' => 'Un promemoria viene inviato prima di ogni appuntamento confermato (Impostazioni prenotazioni › Notifiche).',
'Bkm_Guide_Messages_4' => 'Attivi "Invia anche tramite WhatsApp" per inviare lì gli stessi messaggi.',
'Bkm_Guide_Messages_5' => 'Ogni messaggio è elencato sulla prenotazione, con il motivo del mancato invio quando non è stato inviato.',
'Bkm_Guide_Customers' => 'Clienti, CRM e portale',
'Bkm_Guide_Customers_1' => 'Una prenotazione dal sito web viene aggiunta ai Suoi clienti; chi prenota di nuovo con la stessa email e lo stesso telefono viene riconosciuto.',
'Bkm_Guide_Customers_2' => 'Con il CRM nel Suo piano, le prenotazioni possono essere annotate sul cliente o sul suo lead, e le richieste possono aprire una trattativa.',
'Bkm_Guide_Customers_3' => 'I clienti con un account sul portale clienti vi vedono le proprie prenotazioni e possono annullarle o rispondere a un orario proposto.',
'Bkm_Guide_Customers_4' => 'I clienti del negozio che hanno effettuato l\'accesso trovano le proprie prenotazioni in Il mio account.',
'Bkm_Guide_Roles' => 'Chi può fare cosa',
'Bkm_Guide_Roles_Help' => 'Assegni a ciascun ruolo solo le autorizzazioni di cui ha bisogno (Impostazioni › Autorizzazioni di gruppo).',
'Bkm_Guide_Job' => 'Mansione',
'Bkm_Guide_Give' => 'Autorizzazioni da assegnare',
'Bkm_Guide_Job_Front_Desk' => 'Reception',
'Bkm_Guide_Job_Staff_Member' => 'Operatore',
'Bkm_Guide_Job_Manager' => 'Responsabile',
'Bkm_Guide_Job_Owner' => 'Titolare o contabile',
'Bkm_Guide_Faq' => 'Domande',
'Bkm_Guide_Faq_1_Q' => 'Perché un servizio non compare sul sito web?',
'Bkm_Guide_Faq_1_A' => 'Servono i dettagli di prenotazione (Servizi), "Mostra sul sito web" attivo, il prodotto attivo e, per scegliere un orario, una persona prenotabile online che lo svolga.',
'Bkm_Guide_Faq_2_Q' => 'Perché non ci sono orari liberi?',
'Bkm_Guide_Faq_2_A' => 'Verifichi gli orari di lavoro del personale, i giorni di riposo, le festività e i permessi approvati, il preavviso minimo e con quanti giorni di anticipo i clienti possono prenotare.',
'Bkm_Guide_Faq_3_Q' => 'Due clienti possono prenotare lo stesso orario?',
'Bkm_Guide_Faq_3_A' => 'No. L\'orario viene verificato di nuovo al momento della prenotazione e una prenotazione riservata o confermata lo blocca. I corsi condividono i posti fino al loro limite.',
'Bkm_Guide_Faq_4_Q' => 'Cosa succede quando una riserva scade?',
'Bkm_Guide_Faq_4_A' => 'L\'orario torna libero per gli altri. La prenotazione resta in Richieste finché Lei non risponde (oppure viene annullata se il suo acconto non è stato pagato).',
'Bkm_Guide_Faq_5_Q' => 'I clienti hanno bisogno di un account?',
'Bkm_Guide_Faq_5_A' => 'No. Ricevono un link privato alla pagina della loro prenotazione. Anche gli account del negozio e del portale elencano le loro prenotazioni.',
'Bkm_Guide_Faq_6_Q' => 'Dove vanno i soldi?',
'Bkm_Guide_Faq_6_A' => 'Gli acconti vanno al Suo fornitore di pagamenti; il resto viene incassato al POS quando addebita la prenotazione. I report conteggiano i ricavi da queste vendite.',
'Bkm_Guide_Faq_7_Q' => 'Perché un cliente non ha ricevuto un\'email?',
'Bkm_Guide_Faq_7_A' => 'Apra la prenotazione: il suo elenco messaggi indica se ogni email è stata inviata, non è riuscita o è stata saltata, e perché.',
'Bkm_Staff_Removed' => 'rimosso',
'Bkm_Staff_Not_Bookable' => 'Non più prenotabile',
'Bkm_Requests_Cut' => 'Vengono mostrate le {n} più vecchie. Risponda ad alcune per vedere le altre, oppure usi la ricerca.',

