'Pf_Guide_1' => 'In Printful, aggiunga un negozio di tipo {store} e vi progetti i Suoi prodotti.',
'Pf_Guide_2' => 'Crei un token privato su {portal} per quel negozio con gli ambiti {scopes}. Lo incolli nella scheda Connessione e salvi; se il token dà accesso a più negozi, ne scelga uno.',
'Pf_Guide_3' => 'Il primo test di connessione riuscito registra i webhook, così Printful può comunicare a Stocky le modifiche agli ordini e le spedizioni.',
'Pf_Guide_4' => 'Scheda Prodotti: Importa prodotti. I prodotti con prezzo in una valuta diversa dalla Sua vengono importati come inattivi finché non imposta un tasso di cambio nella scheda Impostazioni o non li prezza manualmente.',
