'Mkg_Guide_Roles' => 'Chi ha bisogno di quale autorizzazione',
'Mkg_Guide_Roles_Help' => 'Dia a ogni ruolo solo ciò di cui ha bisogno in Impostazioni > Autorizzazioni. Una qualsiasi di queste apre questa guida.',
'Mkg_Guide_Permission' => 'Autorizzazione',
'Mkg_Guide_Allows' => 'Consente di',
'Mkg_Guide_Perm_marketing_dashboard' => 'Vedere la dashboard marketing: totali e campagne recenti.',
'Mkg_Guide_Perm_marketing_campaigns' => 'Creare, modificare, inviare ed eliminare campagne e vederne i destinatari.',
'Mkg_Guide_Perm_marketing_segments' => 'Creare e modificare segmenti di clienti.',
'Mkg_Guide_Perm_marketing_templates' => 'Gestire i modelli SMS, WhatsApp ed email.',
'Mkg_Guide_Perm_marketing_reports' => 'Aprire i report di marketing.',
'Mkg_Guide_Perm_marketing_settings' => 'Configurare i canali (SMS, WhatsApp, mittente email), la pianificazione e la dimensione dei lotti.',
'Mkg_Guide_Faq' => 'Domande frequenti',
'Mkg_Guide_Faq_1_Q' => 'La mia campagna resta in Invio e non parte nulla.',
'Mkg_Guide_Faq_1_A' => 'Il processo di invio in background non l\'ha ancora presa in carico. Dopo 30 minuti senza progressi ricompare il pulsante Invia ora: faccia clic per riprendere. Se succede spesso, chieda all\'amministratore della piattaforma di verificare che i processi in background (il queue worker) siano in esecuzione.',
'Mkg_Guide_Faq_2_Q' => 'I destinatari mostrano "Skipped: Email channel disabled" (canale email disattivato).',
'Mkg_Guide_Faq_2_A' => 'Attivi Abilita email nelle Impostazioni marketing, poi invii di nuovo la campagna.',
'Mkg_Guide_Faq_3_Q' => 'I destinatari mostrano "No mail server configured" (nessun server di posta configurato).',
'Mkg_Guide_Faq_3_A' => 'Le campagne email passano solo dal Suo server di posta. Lo aggiunga in Impostazioni > Impostazioni di posta.',
'Mkg_Guide_Faq_4_Q' => 'Il messaggio è arrivato a meno persone di quelle presenti nel mio segmento.',
'Mkg_Guide_Faq_4_A' => 'I clienti senza indirizzo email (Email) o numero di telefono (SMS, WhatsApp) vengono saltati. Apra la campagna per vedere chi è stato saltato e perché.',
'Mkg_Guide_Faq_5_Q' => 'Inviato significa che il cliente l\'ha ricevuto?',
'Mkg_Guide_Faq_5_A' => 'Inviato significa che il server di posta o il gateway ha accettato il messaggio. La consegna nella casella, le aperture e i filtri antispam non vengono tracciati.',
'Mkg_Guide_Faq_6_Q' => 'Posso modificare una campagna dopo averla inviata?',
'Mkg_Guide_Faq_6_A' => 'No. Le campagne in invio e inviate sono bloccate; crei invece una nuova campagna.',
'Mkg_Guide_Faq_7_Q' => 'I miei messaggi WhatsApp non arrivano.',
'Mkg_Guide_Faq_7_A' => 'Trascorse più di 24 ore dall\'ultimo messaggio del cliente, WhatsApp consegna solo modelli approvati da Meta. Usi la WhatsApp Cloud API e scelga un modello approvato nella campagna.',
'Mkg_Guide_Faq_8_Q' => 'Se invio di nuovo una campagna, i clienti la riceveranno due volte?',
'Mkg_Guide_Faq_8_A' => 'Riprendere una campagna bloccata invia solo ai destinatari ancora in sospeso, quindi nessuno già raggiunto riceve di nuovo il messaggio. Inviare di nuovo una campagna non riuscita riparte da zero con un nuovo elenco.',

