'Pd_Installments' => 'Rate',
'Pd_Single_Payment' => 'Pagamento unico',
'Pd_Guide_How_Title' => 'Come funziona',
'Pd_Guide_How_Intro' => 'Un dispositivo POS è un terminale di pagamento o un registratore di cassa fiscale accanto alla cassa. Stocky gli invia l\'importo, attende che il cliente paghi e registra il pagamento solo dopo l\'approvazione del dispositivo.',
'Pd_Guide_Step_1' => 'Aggiunga qui il dispositivo: modello, magazzino e il metodo di pagamento con cui vengono registrati i suoi pagamenti con carta (ad esempio "Carta di credito").',
'Pd_Guide_Step_2' => 'Scelga come Stocky lo raggiunge: un bridge locale sul computer di cassa o l\'API cloud del fornitore. Inserisca gli ID e le chiavi forniti dalla banca o dal fornitore.',
'Pd_Guide_Step_3' => 'Prema Verifica connessione. I dispositivi con bridge devono essere testati dal computer di cassa su cui è in esecuzione il bridge.',
'Pd_Guide_Step_4' => 'Sul POS, scelga quel metodo di pagamento, prema "Addebita sul dispositivo" e lasci pagare il cliente. La vendita può essere completata una volta che il dispositivo approva.',
'Pd_Guide_Step_5' => 'Controlli Transazioni per i pagamenti con carta incassati senza vendita (ad esempio un checkout abbandonato) e li storni o rimborsi.',
'Pd_Guide_Bridge_Text' => 'Per i dispositivi gestiti da un SDK del produttore sul PC di cassa (associazione USB, seriale o LAN). Il browser non può usare direttamente l\'SDK, quindi un piccolo programma bridge lo incapsula e resta in ascolto su questo computer.',
'Pd_Guide_Bridge_Point_1' => 'Il POS invia ogni richiesta all\'URL del bridge dal browser del cassiere; il server di Stocky non ha mai bisogno di raggiungere la rete del negozio.',
'Pd_Guide_Bridge_Point_2' => 'Richieste e risposte sono firmate con il segreto condiviso, quindi un\'approvazione non può essere falsificata dal browser.',
'Pd_Guide_Bridge_Point_3' => 'Installi e avvii il bridge su ogni computer che incassa pagamenti con carta su questo dispositivo.',
'Pd_Guide_Cloud_Text' => 'Per i fornitori che raggiungono il dispositivo via internet. Il server di Stocky chiama l\'API, quindi non occorre installare nulla sul computer di cassa.',
'Pd_Guide_Cloud_Point_1' => 'L\'URL dell\'API deve essere https:// su un indirizzo pubblico.',
'Pd_Guide_Cloud_Point_2' => 'Mentre il cliente paga, Stocky chiede lo stato ogni 2 secondi, quindi l\'endpoint di stato deve riconoscere il pagamento dal suo riferimento; se l\'API risponde prima che la carta abbia finito ("pending"), decide il polling.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'L\'IDE280 è un registratore di cassa fiscale di nuova generazione (YN ÖKC) con lettore di carte. Di norma viene integrato tramite l\'SDK ECR / GMP3 di Ingenico, o tramite il servizio di integrazione della Sua banca.',
'Pd_Guide_Ide280_Point_1' => 'Associ il dispositivo al computer di cassa come descritto nella documentazione Ingenico / della banca, poi punti il bridge (o le impostazioni API) su di esso.',
'Pd_Guide_Ide280_Point_2' => 'Gli importi vengono inviati sia come decimali sia in kuruş (amount_minor), con valuta TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Con "Scontrino fiscale completo", ogni articolo riporta il reparto del dispositivo della sua aliquota IVA: faccia corrispondere i reparti IVA alla programmazione del dispositivo.',
'Pd_Guide_Protocol_Title' => 'Contratto bridge / API',
'Pd_Guide_Protocol_Intro' => 'Stocky comunica in JSON con il bridge o l\'API. I percorsi sotto sono quelli predefiniti e possono essere modificati per ogni dispositivo in Avanzate.',
'Pd_Guide_Operation' => 'Operazione',
'Pd_Guide_Default_Endpoint' => 'Endpoint predefinito',
'Pd_Guide_When' => 'Quando',
'Pd_Guide_When_Ping' => 'Pulsante Verifica connessione.',
'Pd_Guide_When_Sale' => 'Il cassiere preme "Addebita sul dispositivo". Può rispondere quando la carta ha finito, oppure subito con stato "pending".',
'Pd_Guide_When_Status' => 'Ogni 2 secondi mentre il pagamento è in sospeso.',
'Pd_Guide_When_Cancel' => 'Il cassiere annulla mentre attende la carta.',
'Pd_Guide_When_Void' => 'Storno di un pagamento (stesso giorno, intero importo).',
'Pd_Guide_When_Refund' => 'Rimborso parziale o totale di un pagamento.',
'Pd_Guide_Request_Title' => 'Richiesta',
'Pd_Guide_Request_Text' => 'Il corpo che Stocky invia per una vendita. Rimborso e storno includono il pagamento originale come "original".',
'Pd_Guide_Response_Title' => 'Risposta',
'Pd_Guide_Response_Text' => 'I nomi dei campi vengono letti in modo flessibile (anche sotto "data"); "status" o response_code "00" determina l\'esito. I numeri delle carte vengono memorizzati mascherati.',
'Pd_Guide_Signing_Title' => 'Firma (bridge)',
'Pd_Guide_Signing_Text' => 'Il bridge deve verificare la firma di Stocky, deve firmare il corpo esatto della propria risposta e restituire sia "reference" sia "operation": le risposte non firmate, o relative a un\'altra operazione, vengono rifiutate.',
'Pd_Guide_Browser_Title' => 'Accesso dal browser (bridge)',
'Pd_Guide_Browser_Text' => 'La pagina POS chiama il bridge dal browser, quindi il bridge deve rispondere con questi header CORS (incluso il preflight OPTIONS).',
'Pd_Guide_Safety_Title' => 'Da sapere',
'Pd_Guide_Safety_1' => 'Una vendita viene salvata solo con un pagamento approvato dal dispositivo per lo stesso importo; un pagamento del dispositivo non può mai pagare due vendite.',
'Pd_Guide_Safety_2' => 'Chiudere la finestra di pagamento dopo l\'addebito di una carta storna prima quell\'addebito.',
'Pd_Guide_Safety_3' => 'Se il dispositivo non risponde in tempo, il pagamento risulta come "Nessuna risposta": controlli il dispositivo e storni l\'addebito da Transazioni se la carta è stata addebitata.',
'Pd_Guide_Safety_4' => 'Rimborsi e storni qui movimentano denaro solo sulla carta; non modificano la vendita. Registri la merce restituita in Resi di vendita.',
'Perm_Pos_Terminals_Manage' => 'Dispositivi POS: gestire, rimborsare e stornare',
'Perm_Pos_Terminals_Transactions' => 'Dispositivi POS: visualizzare le transazioni',
'Pd_Check_Again' => 'Verifica di nuovo',
'Pd_Lost_Track' => 'Contatto perso prima della risposta del dispositivo. Controlli il dispositivo, poi prema "Verifica di nuovo": non addebiti di nuovo finché non ne è certo.',
'Pd_Close_Anyway' => 'Non è stato possibile stornare il pagamento con carta. Chiudere comunque? Resta in Dispositivi POS › Transazioni come "Addebitato senza vendita", così potrà essere stornato o rimborsato da lì.',
'Pd_Devices_Loading' => 'Caricamento dei dispositivi di pagamento: riprovi tra un momento.',
'Pd_Devices_Unavailable' => 'Non è stato possibile caricare i dispositivi di pagamento, quindi questo metodo di pagamento non può essere usato ora. Scelga un altro metodo o riapra la finestra di pagamento.',
'Pd_Saving_Sale' => 'La vendita è in fase di salvataggio: attenda un momento.',
'Pd_Check_Status' => 'Verifica stato',
