'Adjustment_Stock_Change' => 'Variazione delle giacenze',
'Adjustment_Delete_Impact' => 'L\'eliminazione di questo registro modifica le giacenze di {products} prodotto/i: {removed} unità vengono scalate dalle giacenze e {restored} unità vengono ripristinate.',
'Imp_Update_Only_Desc_Blank' => 'Questa importazione aggiorna i prodotti ESISTENTI per codice: costo, prezzo al dettaglio, nome, categoria, sottocategoria e marca. Una cella vuota lascia invariato quel valore. Non crea mai prodotti.',
'Imp_One_Row_Per_Product_Blank_Unchanged' => 'Una riga per prodotto · codice obbligatorio · le celle vuote restano invariate',
