'Api_Ep_Upsert' => 'Crea o aggiorna un prodotto per codice',
'Api_Ep_Upsert_Notes' => 'Un codice sconosciuto crea un prodotto standard (nome, categoria, unità, costo e prezzo obbligatori). Un codice noto aggiorna solo i campi inviati. Un codice variante aggiorna i prezzi di quella variante. barcodes sostituisce l\'elenco dei codici a barre aggiuntivi.',
'Api_Ep_Stock' => 'Livelli di giacenza',
