'Api_Ep_Purchase' => 'Crea un acquisto',
'Api_Ep_Purchase_Notes' => 'Quantità in unità di acquisto; se manca il costo si usa il costo attuale del prodotto. Un acquisto ricevuto aggiunge subito le giacenze. Lo stesso riferimento di fattura fornitore usato due volte viene rifiutato, a meno che allow_duplicate_reference non sia true.',
