'List_Too_Big_All' => 'Questo elenco ha più di {count} righe, quindi l\'opzione Tutti è disattivata. Vengono mostrate 100 righe per pagina. Usi la ricerca o i filtri per restringerlo.',
'List_Too_Big_Export' => 'Questo elenco ha più di {count} righe, troppe per esportarle in una sola volta. Usi la ricerca o i filtri per restringerlo.',
'PartiallyPaid' => 'Parzialmente pagato',
'Ord_Guide_PayAuto_Tip' => 'Si aggiorna da solo quando vengono registrati pagamenti sulla vendita. Clicchi per vedere come registrare un pagamento.',
'Ord_Guide_PayAuto_Intro' => 'Questa colonna mostra quanto dell\'ordine è stato pagato. Parte dalla scelta fatta dal cliente al checkout, poi si aggiorna da sola man mano che vengono registrati pagamenti sulla vendita creata dalla conferma dell\'ordine. Non può essere modificata da questa pagina.',
'Ord_Guide_PayAuto_Paid' => 'L\'importo totale è stato incassato. Se il cliente ha pagato online tramite un gateway di pagamento, la conferma dell\'ordine crea la vendita come Pagato e registra il pagamento per Lei. Altrimenti lo stato diventa Pagato quando i pagamenti sulla vendita coprono il totale.',
'Ord_Guide_PayAuto_Partial' => 'Sulla vendita è stato registrato un pagamento, ma parte del totale è ancora da pagare.',
'Ord_Guide_PayAuto_Pending' => 'Non è stato ancora ricevuto alcun pagamento: contrassegno, bonifico bancario o un altro metodo di pagamento posticipato. La conferma dell\'ordine crea la vendita come Non pagato, quindi registrerà Lei il denaro una volta incassato. Veda i passaggi qui sotto.',
'Ord_Guide_PayAuto_Note' => 'Lo Stato del pagamento mostrato qui segue la vendita: passa da solo a Parzialmente pagato o Pagato quando salva un pagamento, e torna indietro se ne elimina uno. La vendita è la registrazione contabile ed è ciò che alimenta i report su pagamenti e profitti. Usi Mostra pagamenti sulla vendita per rivedere o modificare quanto inserito.',
'Ord_LinkedSale' => 'Vendita collegata',
