'Oc_Auto_Stock' => 'Invia giacenze automaticamente',
'Oc_Auto_Stock_Help' => 'Ogni movimento di giacenza aggiorna il negozio, e tutte le giacenze vengono controllate una volta all\'ora.',
'Oc_Auto_Products' => 'Invia automaticamente le modifiche ai prodotti',
'Oc_Auto_Products_Help' => 'Un prodotto creato o modificato qui aggiorna il negozio: nome, prezzo, stato e giacenza.',
'Oc_Order_Statuses' => 'Stati degli ordini',
'Oc_Order_Statuses_Help' => 'Cosa significa qui ciascuno stato di OpenCart. Sono stati impostati dal Suo negozio e vanno modificati solo se usa stati personalizzati.',
'Oc_Commit_Statuses' => 'Vendita completata',
