'Oc_Variants_Linked' => 'Varianti collegate',
'Oc_Push_Desc' => 'Crea in OpenCart i prodotti e le varianti mancanti e aggiorna nome, prezzo, stato e giacenza su quelli collegati. Descrizioni, immagini e categorie vengono impostate solo quando un prodotto è nuovo o non ne ha, così i testi scritti in OpenCart restano.',
'Oc_Pull_Desc' => 'Importa i prodotti di OpenCart, abbinando quelli esistenti per modello o SKU e creando gli altri. I prodotti collegati prendono nome e prezzo da OpenCart.',
'Oc_Pull_Stock' => 'Usa le quantità di OpenCart come giacenza iniziale per i nuovi prodotti',
'Oc_Reset_Confirm' => 'Reimpostare i collegamenti dei prodotti? Lo storico ordini mantiene i propri collegamenti.',
'Oc_Stock_Desc' => 'Imposta la quantità nel negozio di ogni prodotto e variante collegati sulla giacenza presente qui.',
'Oc_Orders_Desc' => 'Importa gli ordini del negozio come vendite (riferimenti come {ref}). Per gli ordini già importati vengono aggiornati solo stato e pagamento, quindi recuperarli di nuovo è sicuro.',
'Oc_Orders_Since' => 'Ordini dal',
'Oc_Guide_1' => 'Nella scheda Connessione, scarichi il {company} Connector.',
