'Oc_Guide_3' => 'Apra il modulo {name}, poi copi l\'URL del negozio e il segreto.',
'Oc_Guide_4' => 'Li incolli nella scheda Connessione, salvi ed esegua {test}. In questo modo il negozio sa anche dove inviare i nuovi ordini.',
'Oc_Guide_5' => 'Configuri i prodotti: li recuperi se il negozio ha già un catalogo, li invii se ce l\'ha {company}. Lo faccia prima di affidarsi alle giacenze automatiche, perché {company} diventa la fonte dei dati di giacenza.',
'Oc_Guide_6' => 'Recuperi una volta gli ordini recenti se desidera lo storico. Da quel momento gli ordini arrivano da soli.',
'Oc_Identity_Title' => 'I prodotti vengono abbinati per modello e SKU',
'Oc_Identity_Desc' => 'Il codice prodotto qui viene abbinato al modello e allo SKU di OpenCart. Li mantenga uguali su entrambi i lati. La giacenza qui è il dato di riferimento: il negozio viene aggiornato in base a essa dopo ogni ordine.',
'Oc_Options_Title' => 'Opzioni senza varianti',
'Oc_Options_Desc' => 'Le varianti di OpenCart hanno una propria giacenza e corrispondono alle varianti qui. Un prodotto che ha solo opzioni, senza varianti create, viene importato come un unico prodotto e la sua giacenza non viene suddivisa per opzione.',
'Oc_Cancel_Title' => 'Ordini annullati',
'Oc_Cancel_Desc' => 'L\'annullamento di un ordine in OpenCart storna qui la relativa vendita. Se la vendita era già consegnata o ha un reso, non viene annullato nulla: la vendita viene segnalata nelle note e nei log perché Lei la verifichi.',
'Oc_Download_Connector_3' => 'Scarica per OpenCart 3',
'Oc_Opencart3_Title' => 'Negozi OpenCart 3',
'Oc_Opencart3_Desc' => 'OpenCart 3 non ha varianti proprie, solo opzioni. Un prodotto con una sola opzione (ad esempio Taglia) viene sincronizzato con la giacenza per valore di opzione, che corrisponde alle varianti qui. Per un prodotto con più opzioni le opzioni vengono create senza giacenza per combinazione: la sua giacenza è tenuta sul prodotto nel suo insieme e le righe di vendita arrivano sul prodotto.',
'Oc_G_Title' => 'Guida OpenCart',
