'Oc_G_Your_Setup' => 'La Sua configurazione',
'Oc_G_Your_Setup_Help' => 'A che punto è questo spazio di lavoro. I passaggi si aggiornano man mano che procede.',
'Oc_G_Step_Install' => 'Installare il {company} Connector sul negozio',
'Oc_G_Step_Install_Help' => 'Una piccola estensione che dà a {company} accesso a prodotti, giacenze e ordini. OpenCart da solo non dispone di un\'API per questi dati.',
'Oc_G_Step_Connect' => 'Collegare il negozio',
'Oc_G_Step_Connect_Help' => 'Incolli l\'URL del negozio e il segreto dalla pagina del modulo nella scheda Connessione, salvi, poi esegua Testa la connessione.',
'Oc_G_Step_Connect_Done' => 'Connesso: connettore {connector} su OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Attivare la sincronizzazione',
'Oc_G_Step_Enable_Help' => 'Nulla si muove mentre l\'integrazione è disattivata; i webhook dal negozio vengono confermati e ignorati.',
'Oc_G_Step_Products' => 'Collegare i prodotti',
'Oc_G_Step_Products_Help' => 'Recuperi il catalogo del negozio o invii il Suo, così ogni prodotto su entrambi i lati è collegato prima che le giacenze inizino a fluire.',
'Oc_G_Step_Products_Done' => '{n} prodotti e {v} varianti collegati.',
'Oc_G_Step_Orders' => 'Ricevere gli ordini',
'Oc_G_Step_Orders_Help' => 'Una volta connesso, i nuovi ordini arrivano da soli. Effettui un ordine di prova nel negozio per vederlo comparire in Vendite.',
'Oc_G_Step_Orders_No_Webhook' => 'Gli ordini sono stati importati, ma nessuno è ancora arrivato tramite la notifica del negozio. Se il negozio non riesce a raggiungere questo indirizzo, gli ordini arrivano comunque con il controllo eseguito ogni pochi minuti.',
'Oc_G_Step_Orders_Done' => 'Il negozio sta inviando le notifiche degli ordini.',
'Oc_G_Install_Title' => 'Installare il connettore',
'Oc_G_Install_Intro' => 'Scelga la Sua versione di OpenCart. Il connettore si installa tramite l\'installer di estensioni di OpenCart; nessun file va modificato a mano.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Scarichi il connettore per OpenCart 4.',
'Oc_G_I4_2' => 'Nell\'amministrazione di OpenCart, apra {path}, carichi il file e clicchi su Install accanto a esso.',
'Oc_G_I4_3' => 'Apra {path}, trovi {name} e clicchi su Install, poi su Edit.',
'Oc_G_I3_1' => 'Scarichi il connettore per OpenCart 3.',
'Oc_G_I3_2' => 'Nell\'amministrazione di OpenCart, apra {path}, carichi il file e attenda il completamento dei passaggi.',
'Oc_G_I3_3' => 'Apra {path}, trovi {name} e clicchi su Install, poi su Edit.',
'Oc_G_I_4' => 'La pagina del modulo mostra l\'URL del negozio e un segreto. Li copi entrambi.',
'Oc_G_I_5' => 'Tornato qui, li incolli nella scheda Connessione, salvi ed esegua {test}. In questo modo il negozio sa anche dove inviare le notifiche degli ordini.',
'Oc_G_Requirements' => 'Di cosa ha bisogno il negozio',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 o 4.0 e successivi, PHP con cURL (standard su qualsiasi hosting) e un indirizzo del negozio raggiungibile da Internet. Se il negozio si trova su una rete privata, gli ordini arrivano comunque tramite il controllo eseguito ogni pochi minuti, purché questo spazio di lavoro possa raggiungere il negozio.',
'Oc_G_First_Title' => 'La prima sincronizzazione',
'Oc_G_First_Shop_Has' => 'Il negozio ha già il catalogo',
'Oc_G_First_Shop_Has_Text' => 'Recuperi i prodotti nella scheda Prodotti. I prodotti vengono abbinati ai Suoi codici prodotto per modello o SKU e creati se mancanti; spunti l\'opzione della giacenza per usare le quantità del negozio come giacenza iniziale.',
'Oc_G_First_Company_Has' => 'Il catalogo è in {company}',
'Oc_G_First_Company_Has_Text' => 'Invii i prodotti. I prodotti mancanti vengono creati nel negozio con la loro giacenza; quelli esistenti vengono collegati per modello o SKU e aggiornati.',
'Oc_G_First_Both' => 'Entrambi i lati hanno prodotti',
'Oc_G_First_Both_Text' => 'Prima li recuperi, così i prodotti esistenti del negozio vengono collegati anziché duplicati, poi li invii per creare ciò che manca nel negozio. Mantenga uguali codici prodotto e modelli su entrambi i lati.',
'Oc_G_Stock_Master' => 'La giacenza di riferimento è in {company}',
'Oc_G_Stock_Master_Desc' => 'Dopo la prima sincronizzazione, la quantità nel negozio viene sempre scritta da {company}. Modificare una quantità in OpenCart non ha effetto duraturo: il movimento successivo o il controllo orario la sovrascrive.',
'Oc_G_How_Title' => 'Come funziona',
'Oc_G_T_Products' => 'Prodotti',
'Oc_G_Products_1' => 'Un prodotto viene abbinato tramite il suo codice qui al modello e allo SKU nel negozio. Il collegamento viene memorizzato, quindi rinominare un prodotto in seguito non lo interrompe.',
'Oc_G_Products_2' => 'Quando {company} invia un prodotto, imposta modello, SKU, nome, prezzo, stato e giacenza. Descrizione, immagine e categoria vengono scritte solo quando il prodotto è nuovo nel negozio o non ne ha, così i testi scritti in OpenCart restano.',
'Oc_G_Products_3' => 'Un prodotto nascosto dal negozio online o non in vendita qui non viene creato nel negozio; uno già collegato viene invece impostato come disattivato lì.',
'Oc_G_T_Variants' => 'Varianti e opzioni',
'Oc_G_Variants_4' => 'OpenCart 4 ha vere varianti (un prodotto con scelte di Colore e Taglia), ciascuna con la propria giacenza. Corrispondono alle Sue varianti in entrambe le direzioni e ognuna viene abbinata tramite il proprio modello.',
'Oc_G_Variants_3' => 'OpenCart 3 non ha varianti, solo opzioni, e giacenza per valore di opzione. Un prodotto con una sola opzione (ad esempio Taglia) viene sincronizzato con la giacenza per valore, che corrisponde alle Sue varianti. Per un prodotto con più opzioni le opzioni vengono create senza giacenza per combinazione: la sua giacenza resta sul prodotto nel suo insieme e le righe di vendita arrivano sul prodotto.',
'Oc_G_Variants_Multi' => 'Un prodotto del negozio che ha solo opzioni, senza varianti create, viene importato come un unico prodotto; ciò viene annotato nei log.',
'Oc_G_T_Stock' => 'Giacenze',
'Oc_G_Stock_1' => 'Con l\'interruttore delle giacenze attivo, ogni movimento qui (una vendita, un reso, un acquisto, una rettifica, un trasferimento) aggiorna il negozio in pochi secondi, dopo che la pagina ha risposto, così il cassiere non attende mai il negozio.',
'Oc_G_Stock_2' => 'Una volta all\'ora ogni prodotto collegato viene controllato e corretto, il che copre le modifiche massive che l\'invio in tempo reale non vede. La scheda Giacenze invia tutto su richiesta.',
'Oc_G_Stock_3' => 'Servizi, prodotti contrassegnati come sempre disponibili e combo i cui componenti sono illimitati vengono mostrati nel negozio come sempre disponibili. Scelga un magazzino nella scheda Connessione per conteggiare solo quel magazzino; altrimenti vengono sommati tutti i magazzini.',
'Oc_G_T_Orders' => 'Ordini e stati',
'Oc_G_Orders_1' => 'Un ordine nuovo o modificato viene annunciato subito dal negozio e riletto tramite la connessione firmata, quindi nulla nella notifica stessa viene considerato attendibile. Ogni pochi minuti un controllo recupera ciò che una notifica ha mancato. Ogni ordine diventa una vendita con riferimento OC-<order number>; il cliente viene abbinato tramite email o creato.',
'Oc_G_Col_List' => 'Elenco stati',
'Oc_G_Col_Meaning' => 'Cosa fa qui',
'Oc_G_Col_Default' => 'Impostato dal Suo negozio',
'Oc_G_Default_Commit' => 'Gli stati che scalano la giacenza in OpenCart (per impostazione predefinita Pending, Processing, Shipped, Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Gli elenchi vengono compilati dal Suo negozio alla prima connessione e possono essere modificati nella scheda Connessione. Mantenga il primo elenco uguale agli stati che scalano la giacenza in OpenCart, così entrambi i lati movimentano la giacenza nello stesso passaggio.',
'Oc_G_Orders_3' => 'Un ordine con un articolo che non corrisponde ad alcun prodotto viene messo in attesa e il prodotto viene importato dal negozio, se lì esiste. Gli ordini in attesa vengono ritentati a ogni controllo pianificato; dopo dodici tentativi vengono registrati nei log e lasciati da recuperare a mano.',
'Oc_G_T_Cancel' => 'Annullamenti e rimborsi',
'Oc_G_Cancel_1' => 'Quando un ordine raggiunge uno stato annullato nel negozio, la relativa vendita qui viene stornata: la giacenza rientra, i pagamenti vengono rimossi e la vendita viene eliminata, esattamente come farebbe la sua eliminazione dalla pagina Vendite.',
'Oc_G_Cancel_2' => 'Una vendita già consegnata, con un reso o accettata da un\'autorità fiscale non viene mai stornata dal negozio. Viene segnalata nelle note e nei log perché Lei la verifichi.',
'Oc_G_Cancel_3' => 'Se in seguito l\'ordine viene ripristinato nel negozio, arriva di nuovo come nuova vendita.',
'Oc_G_T_Automation' => 'Interruttori di automazione',
'Oc_G_Auto_1' => 'Importa ordini automaticamente: notifiche degli ordini e controllo pianificato. Se disattivato, gli ordini arrivano solo quando li recupera nella scheda Ordini.',
'Oc_G_Auto_2' => 'Invia giacenze automaticamente: aggiornamenti delle giacenze in tempo reale e controllo orario. Se disattivato, il negozio cambia solo quando invia le giacenze a mano.',
'Oc_G_Auto_3' => 'Invia automaticamente le modifiche ai prodotti: un prodotto creato o modificato qui aggiorna subito il negozio. Se disattivato, usi la scheda Prodotti.',
'Oc_G_T_Faq' => 'Domande',
'Oc_G_Q_Secret' => 'Testa la connessione indica che il segreto non corrisponde',
'Oc_G_A_Secret' => 'Apra il modulo {company} Connector in OpenCart e copi di nuovo il segreto; un modulo reinstallato ne riceve uno nuovo. Lo incolli nella scheda Connessione e salvi prima di eseguire il test.',
'Oc_G_Q_Clock' => 'Testa la connessione indica che l\'orologio del negozio è troppo sfasato',
'Oc_G_A_Clock' => 'Le richieste firmate contengono l\'ora e vengono rifiutate quando i due orologi differiscono di più di cinque minuti. Imposti data e ora sul server del negozio.',
'Oc_G_Q_Redirect' => 'Testa la connessione indica che il negozio reindirizza a un altro indirizzo',
'Oc_G_A_Redirect' => 'Il Suo negozio risponde a un indirizzo diverso, di solito https invece di http oppure con www. Usi come URL del negozio l\'indirizzo mostrato nel messaggio.',
'Oc_G_Q_Not_Answering' => 'Testa la connessione indica che il connettore non ha risposto',
'Oc_G_A_Not_Answering' => 'L\'indirizzo non è un negozio OpenCart, oppure il modulo non è installato o è disattivato. Controlli l\'URL del negozio, poi che il {company} Connector risulti installato e abilitato in Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Gli ordini vengono effettuati nel negozio ma impiegano minuti a comparire',
'Oc_G_A_No_Orders' => 'Il negozio non riesce a raggiungere questo spazio di lavoro, quindi gli ordini arrivano solo tramite il controllo pianificato. Controlli l\'indirizzo di {company} nella pagina del modulo: deve essere raggiungibile dal server del negozio. Eseguire Testa la connessione lo registra di nuovo.',
'Oc_G_Q_Stock_Wrong' => 'Una quantità nel negozio è errata',
'Oc_G_A_Stock_Wrong' => 'Invii le giacenze dalla scheda Giacenze, che riscrive ogni prodotto collegato con i dati presenti qui. Se continua a discostarsi, verifichi che l\'interruttore delle giacenze sia attivo e che nessuno modifichi le quantità in OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Un prodotto risulta esaurito nel negozio anche se qui c\'è giacenza',
'Oc_G_A_Out_Of_Stock' => 'Su OpenCart 3 un prodotto con più opzioni tiene la giacenza sul prodotto nel suo insieme; controlli la quantità del prodotto nel negozio anziché quella delle sue opzioni. Per qualsiasi prodotto, invii le giacenze una volta e consulti i log relativi a quel prodotto.',
'Oc_G_Q_Held' => 'I log indicano che un ordine è stato messo in attesa',
'Oc_G_A_Held' => 'Uno dei suoi articoli non corrisponde ad alcun prodotto qui e non è stato possibile importarlo dal negozio, di solito perché lì il prodotto è stato eliminato. Crei o colleghi il prodotto, poi recuperi gli ordini nella scheda Ordini.',
'Oc_G_Q_Deleted_Sale' => 'Ho eliminato una vendita importata ed è ricomparsa',
'Oc_G_A_Deleted_Sale' => 'Finché l\'ordine è attivo nel negozio, la notifica o il controllo successivo lo importa di nuovo. Annulli invece l\'ordine nel negozio: in questo modo la vendita qui viene stornata.',
'Oc_G_Q_Uninstall' => 'Come scollego il negozio?',
'Oc_G_A_Uninstall' => 'Disattivi la sincronizzazione nella scheda Connessione; nulla si muove mentre è disattivata. Per rimuovere l\'integrazione dal negozio, disinstalli il {company} Connector in Extensions → Modules.',
'Oc_Full_Guide' => 'Apri la guida completa',
'Comm_Receipt_Account_Hint' => 'Il conto cassa o bancario da cui esce questo pagamento. Il suo saldo diminuisce dell\'importo e la contabilità registra Spese per commissioni di vendita (Sales Commission Expense) in contropartita.',
'Comm_G_Q_Ledger' => 'Che effetto ha sui conti il pagamento di una commissione?',
'Comm_G_A_Ledger' => 'Quando crea una ricevuta e sceglie un conto, il saldo di quel conto diminuisce dell\'importo della ricevuta e, se le registrazioni automatiche sono attive, viene registrata una scrittura: dare Spese per commissioni di vendita (Sales Commission Expense, 5200-COMM), avere il conto cassa o bancario scelto. Se non viene selezionato alcun conto, l\'avere va sul conto Cassa (Cash) predefinito e nessun saldo cambia.',
'Hide_Zero_Decimals' => 'Nascondi decimali a zero',
'Sys_Hide_Zero_Decimals_Help' => 'Mostra gli importi interi senza decimali: 100.00 diventa 100, mentre 100.50 mantiene i decimali. Solo visualizzazione; i valori salvati e i calcoli non cambiano.',
'Sys_Currency_Position_Before_NoSpace' => 'Prima dell\'importo, senza spazio',
'Sys_Currency_Position_After_NoSpace' => 'Dopo l\'importo, senza spazio',
'Supplier_Wallet' => 'Portafoglio fornitore',
'Supplier_Wallets' => 'Portafogli fornitori',
'Supplier_Ledger' => 'Libro mastro fornitore',
'Sys_Supplier_Wallet_Help' => 'Gestisce saldi prepagati presso i fornitori: ricariche, crediti da resi e pagamento degli acquisti dal portafoglio. Richiede la funzionalità Portafoglio fornitore nel piano.',
'SW_Allow_Negative' => 'Consenti saldo negativo del portafoglio',
'Sys_SW_Allow_Negative_Help' => 'Consente a un pagamento di acquisto di mandare in negativo il portafoglio del fornitore invece di essere rifiutato.',
