'SW_Freeze' => 'Blocca portafoglio',
'SW_Unfreeze' => 'Sblocca portafoglio',
'SW_Freeze_Confirm' => 'Un portafoglio bloccato rifiuta ogni movimento finché non viene sbloccato. Continuare?',
'SW_Unfreeze_Confirm' => 'Consentire di nuovo i movimenti del portafoglio per questo fornitore?',
'SW_Only_With_Balance' => 'Solo portafogli con saldo',
'SW_Top_Up' => 'Ricarica',
'SW_Refund' => 'Rimborso dal portafoglio',
'SW_Adjust' => 'Rettifica saldo',
'SW_Top_Up_Help' => 'Denaro pagato in anticipo al fornitore. Esce dal conto scelto e resta nel portafoglio finché non viene speso per gli acquisti.',
'SW_Refund_Help' => 'Il fornitore restituisce in contanti parte dell\'anticipo. L\'importo esce dal portafoglio ed entra nel conto scelto.',
'SW_Adjust_Help' => 'Correzione manuale senza movimento di cassa. È obbligatorio un motivo, che viene conservato nel libro mastro.',
'SW_Adjust_Credit' => 'Aggiungi al portafoglio',
'SW_Adjust_Debit' => 'Detrai dal portafoglio',
'SW_Pay_From_Wallet' => 'Paga dal portafoglio fornitore',
'SW_Pay_From_Wallet_Help' => 'L\'importo viene prelevato dal saldo prepagato presso questo fornitore. Non servono conto né metodo di pagamento.',
'SW_Credit_To_Wallet' => 'Accredita sul portafoglio fornitore',
'SW_Credit_To_Wallet_Help' => 'Invece di pagare in contanti, il fornitore regola questo reso come credito sul portafoglio, utilizzabile per acquisti successivi.',
'SW_Disabled_Hint' => 'Il Portafoglio fornitore è disattivato. Lo attivi in Impostazioni di sistema > Funzionalità (richiede anche la funzionalità Portafoglio fornitore nel piano).',
'SW_Src_top_up' => 'Ricarica',
'SW_Src_refund' => 'Rimborso',
'SW_Src_adjustment' => 'Rettifica',
'SW_Src_purchase_payment' => 'Pagamento acquisto',
'SW_Src_return_credit' => 'Credito da reso',
'SW_Src_opening_balance_payment' => 'Pagamento saldo iniziale',
'SW_Src_reversal' => 'Storno',
