'SW_Err_wallet_frozen' => 'Questo portafoglio fornitore è bloccato.',
'SW_Err_wallet_insufficient_balance' => 'Saldo del portafoglio insufficiente.',
'SW_Err_wallet_invalid_amount' => 'L\'importo deve essere maggiore di zero.',
'SW_Perm_View' => 'Portafoglio fornitore: visualizzare',
'SW_Perm_Manage' => 'Portafoglio fornitore: gestire',
'SW_Top_Ups_Total' => 'Ricariche (totale)',
'SW_Spent_Total' => 'Speso dal portafoglio',
'Purchases_Grand' => 'Acquisti (totale)',
'Purchases_Paid' => 'Acquisti (pagato)',
'Purchases_Due' => 'Acquisti (da pagare)',
'Purchase_Update_Selling_Price' => 'Modifica prezzo di vendita nell\'acquisto',
'Sys_Purchase_Update_Selling_Price_Help' => 'Aggiunge un campo prezzo di vendita a ogni riga di acquisto, accanto al costo. Un prezzo inserito lì sostituisce il prezzo di vendita del prodotto quando l\'acquisto viene salvato; lo lasci vuoto per mantenere il prezzo attuale.',
'Current_Selling_Price' => 'Prezzo di vendita attuale',
'Keep_Current_Price' => 'Lasci vuoto per mantenere il prezzo attuale',
'Selling_Price_In_Base_Currency' => 'Inserito nella valuta di base',
'Purchase_Update_Product_Cost' => 'Aggiorna costo prodotto nell\'acquisto',
'Sys_Purchase_Update_Product_Cost_Help' => 'Quando viene salvato un acquisto ricevuto, il costo di ciascun prodotto diventa il costo unitario netto della sua riga di acquisto (dopo lo sconto di riga, imposte escluse, per unità di base). Gli acquisti in sospeso e ordinati non lo modificano.',
'Show_Stock_In_Search_Results' => 'Mostra giacenza nei risultati di ricerca',
'Show_Stock_In_Search_Results_Help' => 'Mostra la quantità disponibile di ciascun prodotto accanto a esso nel menu a tendina di ricerca del POS.',
'Layout_6_Tabular' => 'Layout 6 - Tabellare',
'Show_Signature_Line' => 'Mostra riga per la firma',
'Show_Signature_Line_Desc' => 'Stampa una riga vuota per la firma del cliente sotto lo scontrino, qualunque sia il layout selezionato.',
'Customer_Signature' => 'Firma del cliente',
'Set_Signature_Label' => 'Etichetta della riga per la firma (vuoto = "Firma del cliente")',
'Oc_Code_Source' => 'Origine del codice prodotto',
'Oc_Code_Source_Help' => 'Quale campo di OpenCart corrisponde qui al codice prodotto. In OpenCart il modello è obbligatorio, quindi alcuni negozi vi inseriscono una categoria o un tipo di prodotto e tengono il vero codice articolo in SKU, ISBN, UPC, EAN, JAN o MPN; per un negozio del genere scelga quel campo. Quando il campo scelto è vuoto si usano il modello e poi lo SKU. Si applica ai prodotti recuperati, all\'abbinamento e agli invii.',
'Oc_Code_Source_Model' => 'Modello (predefinito)',
'Oc_Code_Source_Sku' => 'SKU',
'Oc_Connector_Link' => 'Sito web del connettore',
'Oc_Connector_Link_Help' => 'L\'indirizzo del Suo sito web. OpenCart vi collega il nome del connettore nella pagina Extensions > Installer. Lasci vuoto per usare l\'indirizzo di questo spazio di lavoro {company}.',
'Store_Warehouses_Help' => 'La giacenza mostrata e scalata online proviene da questi magazzini. Finché "Limita i prodotti per magazzino" è attivo in Funzionalità, il negozio elenca anche solo i prodotti che appartengono a questi magazzini (o vi hanno giacenza).',
'Oc_Code_Source_Needs_Update' => 'Il connettore installato nel negozio (versione {version}) comunica solo il modello e lo SKU. Scarichi di nuovo il connettore e lo carichi sopra quello vecchio nel negozio perché questo campo venga letto.',
'Oc_L_Title' => 'Log OpenCart',
'Oc_L_Intro' => 'Qui viene registrato ogni recupero e invio di prodotti, aggiornamento delle giacenze, ordine e chiamata al negozio. Filtri gli errori per vedere cosa non è riuscito, apra una riga per leggere cosa significa e cosa fare, ed esporti l\'elenco quando deve inviarlo all\'assistenza.',
'Oc_L_Tab_Hint' => 'La pagina completa dei log spiega ogni voce, filtra per azione e data ed esporta in un file.',
'Oc_L_Open_Page' => 'Apri la pagina dei log',
'Oc_L_Entries' => 'Voci',
'Oc_L_Errors' => 'Errori',
'Oc_L_Warnings' => 'Avvisi',
'Oc_L_Last_24h' => 'ultime 24 ore: {n}',
'Oc_L_Last_Error' => 'Ultimo errore',
'Oc_L_Last_Pull' => 'Ultimo recupero prodotti',
'Oc_L_None' => 'Nessuno',
'Oc_L_Store_Total' => 'Il negozio dichiara {n} prodotti per questo negozio.',
'Oc_L_Search' => 'Cerca nei messaggi e nei dettagli',
'Oc_L_All_Levels' => 'Tutti i livelli',
'Oc_L_All_Actions' => 'Tutte le azioni',
'Oc_L_Export' => 'Esporta CSV',
'Oc_L_Export_Help' => 'Esporta l\'elenco filtrato, dal più recente, fino a 5,000 voci.',
'Oc_L_Col_Date' => 'Data',
'Oc_L_Col_Level' => 'Livello',
'Oc_L_Col_Action' => 'Azione',
'Oc_L_Col_Message' => 'Cosa è successo',
'Oc_L_Open_Row' => 'Clicchi su una riga per i dettagli e cosa fare.',
'Oc_L_What_It_Means' => 'Cosa significa',
'Oc_L_What_To_Do' => 'Cosa fare',
