'Oc_L_H_Secret' => 'Il segreto salvato qui non è quello del modulo connettore in OpenCart, quindi il negozio rifiuta ogni chiamata.',
'Oc_L_F_Secret' => 'In OpenCart apra Extensions → Modules → il connettore, copi il segreto mostrato, lo incolli nella scheda Connessione e salvi. Reinstallare il modulo crea un nuovo segreto.',
'Oc_L_H_Clock' => 'L\'orologio del server OpenCart differisce troppo dal nostro, quindi le richieste firmate risultano scadute.',
'Oc_L_F_Clock' => 'Chieda al provider di hosting di impostare l\'ora del server (NTP). Una differenza di pochi minuti basta a bloccare la connessione.',
'Oc_L_H_Disabled' => 'Il modulo connettore è installato in OpenCart ma disattivato.',
'Oc_L_F_Disabled' => 'In OpenCart apra Extensions → Modules → il connettore e imposti Status su Enabled.',
'Oc_L_H_Unreachable' => 'Il negozio non ha risposto all\'indirizzo salvato, oppure il modulo connettore non vi è installato.',
'Oc_L_F_Unreachable' => 'Apra l\'URL del negozio in un browser per verificare che sia online, confermi che il modulo connettore sia installato e abilitato e verifichi che nessun firewall o modalità di manutenzione blocchi il nostro server.',
'Oc_L_H_Redirect' => 'Il negozio indirizza i visitatori a un altro indirizzo (ad esempio da http a https o a www).',
'Oc_L_F_Redirect' => 'Salvi l\'indirizzo indicato nel messaggio come URL del negozio nella scheda Connessione.',
'Oc_L_H_Not_Configured' => 'Manca l\'URL del negozio o il segreto, quindi non è ancora possibile inviare nulla.',
'Oc_L_F_Not_Configured' => 'Compili l\'URL del negozio e il segreto nella scheda Connessione, salvi ed esegua Testa la connessione.',
'Oc_L_H_Model_Taken' => 'Un prodotto inviato al negozio ha un codice che un altro prodotto del negozio, o una delle sue varianti, usa già come modello.',
'Oc_L_F_Model_Taken' => 'Modifichi il codice di uno dei due prodotti, oppure recuperi prima i prodotti così il prodotto esistente del negozio viene collegato invece di essere creato di nuovo.',
'Oc_L_H_Model_Missing' => 'Un prodotto inviato al negozio non ha codice o nome. OpenCart richiede entrambi.',
'Oc_L_F_Model_Missing' => 'Assegni qui al prodotto un codice e un nome, poi lo invii di nuovo.',
'Oc_L_H_Held' => 'È stato ricevuto un ordine, ma alcuni suoi articoli non corrispondono ad alcun prodotto qui, quindi è in attesa e non è stata creata alcuna vendita.',
'Oc_L_F_Held' => 'Crei o recuperi i prodotti mancanti (gli articoli sono elencati sotto), poi recuperi di nuovo gli ordini. Gli ordini in attesa vengono ritentati automaticamente alcune volte.',
'Oc_L_H_Given_Up' => 'Non è stato possibile importare un ordine dopo diversi tentativi e non viene più ritentato.',
'Oc_L_F_Given_Up' => 'Si assicuri che i suoi prodotti esistano qui, poi recuperi gli ordini a mano dalla scheda Ordini con una data anteriore all\'ordine.',
'Oc_L_H_Review' => 'Un ordine è stato annullato in OpenCart dopo che la vendita qui era stata consegnata o resa, quindi la giacenza non è stata stornata automaticamente.',
'Oc_L_F_Review' => 'Apra la vendita e decida se rendere gli articoli o lasciarla com\'è.',
'Oc_L_H_Reversed' => 'Un ordine è stato annullato in OpenCart e la vendita corrispondente qui è stata stornata, ripristinando la giacenza.',
'Oc_L_H_Backlog' => 'Il recupero ordini pianificato ha trovato più ordini di quanti ne elabori in un\'esecuzione e riprenderà la volta successiva.',
'Oc_L_F_Backlog' => 'Recuperi gli ordini a mano dalla scheda Ordini per smaltire l\'arretrato.',
'Oc_L_H_Paused' => 'Gli invii automatici sono stati sospesi per un po\' perché il negozio ha smesso di rispondere. Le modifiche fatte nel frattempo vengono inviate quando torna a rispondere.',
'Oc_L_F_Paused' => 'Verifichi che il negozio sia online. Non serve altro; la coda riprende da sola.',
'Oc_L_H_Busy' => 'Due invii automatici si sono sovrapposti e uno si è fatto da parte. Non è andato perso nulla.',
'Oc_L_H_Codes_Suffixed' => 'Alcuni prodotti recuperati hanno un codice che qui aveva già un altro prodotto del negozio, di solito perché il campo codice scelto è vuoto o contiene il nome di una categoria. Sono stati creati aggiungendo l\'id di OpenCart, così due prodotti non vengono mai uniti.',
'Oc_L_F_Codes_Suffixed' => 'Compili il campo codice (Model, SKU, ISBN…) in OpenCart per i prodotti elencati sotto, oppure scelga un\'altra Origine del codice prodotto nella scheda Connessione, poi reimposti i collegamenti dei prodotti e li recuperi di nuovo.',
'Oc_L_H_Options' => 'Alcuni prodotti del negozio hanno opzioni (taglia, colore…) senza giacenza per variante, quindi la giacenza viene tracciata per il prodotto nel suo insieme.',
'Oc_L_F_Options' => 'Non è richiesto nulla. Per tracciare la giacenza per opzione, trasformi quelle opzioni in varianti in OpenCart 4, oppure usi una sola opzione per prodotto in OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'Questa pagina di prodotti è stata letta dal negozio. Creato significa un nuovo prodotto qui; aggiornato significa che esisteva già ed è stato collegato.',
'Oc_L_H_Pull_Failed' => 'Alcuni prodotti di questa pagina non sono stati salvati qui; ognuno è elencato sotto con il motivo.',
'Oc_L_F_Pull_Failed' => 'Corregga i prodotti elencati in OpenCart (la causa abituale è un nome o un codice mancante) e li recuperi di nuovo. Sono interessati solo quelli non riusciti.',
'Oc_L_H_Push_Warnings' => 'I prodotti sono stati inviati al negozio, ma il negozio ha segnalato problemi con alcuni di essi, ad esempio un\'immagine che non è riuscito a scaricare.',
'Oc_L_F_Push_Warnings' => 'Legga l\'elenco sotto. Le immagini devono essere raggiungibili dal server del negozio; tutto il resto è stato salvato come inviato.',
'Oc_L_H_Missing_Remote' => 'Le giacenze sono state inviate, ma alcuni prodotti collegati non esistono più nel negozio.',
'Oc_L_F_Missing_Remote' => 'Invii i prodotti per ricrearli nel negozio, oppure reimposti i collegamenti dei prodotti se sono stati eliminati di proposito.',
'Oc_L_H_Generic' => 'Un passaggio della sincronizzazione non è riuscito. Il messaggio sopra riporta il motivo indicato dal negozio o dal server.',
'Oc_L_F_Generic' => 'Esegua Testa la connessione nella scheda Connessione. Se riesce, ripeta il passaggio; se non riesce, segua l\'indicazione che fornisce.',
'Oc_L_H_Code_Fallback' => 'Alcuni prodotti di questa pagina sono arrivati senza un valore nel campo scelto come Origine del codice prodotto, quindi come codice è stato usato il loro modello (spesso il nome di una categoria).',
'Oc_L_F_Code_Fallback' => 'Controlli "Prodotti con ciascun campo" qui sotto. Se il campo scelto mostra 0 mentre il negozio ha quei valori, il negozio li conserva con un nome identificativo diverso; apra in OpenCart uno dei prodotti elencati (scheda Data, Product Codes) e ci invii ciò che mostra. Altrimenti compili il campo in OpenCart per i prodotti elencati e li recuperi di nuovo.',
'Oc_L_H_Old_Connector' => 'Il negozio usa ancora un connettore precedente alla 1.1.0, che invia solo il modello e lo SKU, quindi il campo codice scelto non arriva mai ed è stato usato il modello.',
'Oc_L_F_Old_Connector' => 'Scarichi di nuovo il connettore, disinstalli ed elimini quello vecchio in OpenCart (Extensions → Installer), installi quello nuovo, incolli il nuovo segreto nella scheda Connessione ed esegua Testa la connessione. Prima di recuperare i prodotti la pagina deve mostrare Connettore 1.1.0.',
'Oc_L_D_Code_Source' => 'Origine del codice prodotto',
'Oc_L_D_Code_Fallback_Count' => 'Prodotti senza il campo scelto',
'Oc_L_D_Codes_Seen' => 'Prodotti con ciascun campo',
'Oc_L_D_Code_Fallback' => 'Prodotti che hanno usato il modello come codice (#id OpenCart, modello)',
'Oc_L_H_Codes_Fixed' => 'Alcuni prodotti importati in precedenza con il modello come codice ora hanno il campo scelto nel negozio, quindi il loro codice è stato corretto di conseguenza.',
'Oc_L_D_Codes_Fixed' => 'Codici corretti (vecchio → nuovo)',
