'Pg_Auto_Confirm' => 'Conferma automatica degli ordini pagati',
'Pg_Auto_Confirm_Help' => 'Quando un pagamento tramite questo gateway va a buon fine, l\'ordine viene confermato automaticamente: viene creata una vendita e la giacenza viene scalata. Se la giacenza è esaurita, l\'ordine resta in sospeso e ne mostra il motivo.',
'Auto_Confirm_Failed' => 'Pagato, ma non confermato automaticamente',
'Auto_Confirm_Failed_Tag' => 'Non confermato automaticamente',
'Pg_Auto_Confirm_Not_Saved' => 'Non è stato possibile salvare l\'interruttore di conferma automatica. Installi l\'ultimo aggiornamento (migrazioni del database) o verifichi che il Suo ruolo possa modificare le impostazioni del negozio.',
'Warehouse_Prices_Enabled' => 'Prezzi diversi per punto vendita',
'Warehouse_Prices_Enabled_Help' => 'Assegna a un prodotto un prezzo, un prezzo all\'ingrosso e un prezzo minimo propri in ogni magazzino (punto vendita). POS, vendite, preventivi ed etichette con codice a barre usano il prezzo del magazzino selezionato. Il negozio online e le sincronizzazioni dei canali mantengono il prezzo normale, e le vendite già registrate non cambiano.',
'Store_Prices' => 'Prezzi per punto vendita',
'Store_Prices_Help' => 'Lasci vuoto un campo per usare il prezzo normale in quel punto vendita.',
'Store_Prices_Add_Variants_First' => 'Aggiunga prima le varianti, poi ne imposti i prezzi per punto vendita.',
'Store_Prices_Switch_Off' => 'Attivi "Prezzi diversi per punto vendita" in Impostazioni di sistema > Funzionalità per importare i prezzi per punto vendita.',
'Store_Prices_Import_Help' => 'Esporti il foglio, compili le colonne price, wholesale_price e min_price, poi lo reimporti. Una cella vuota significa che in quel punto vendita si applica il prezzo normale. Le colonne product e normal_price sono solo di riferimento. Per una variante, usi il codice della variante.',
'Store_Prices_Only_Set' => 'Solo i prodotti con un prezzo per punto vendita',
'Store_Prices_Export' => 'Esporta prezzi per punto vendita',
'Store_Prices_Import_Done' => 'Prezzi per punto vendita salvati: {created} aggiunti, {updated} aggiornati, {cleared} rimossi.',
'Electronics_Premium_Theme' => 'Electronics Premium',
'Premium_Theme_Not_In_Plan' => 'Premium, non incluso nel Suo piano',
'Premium_Theme_Fallback_Title' => 'Il Suo piano non include i temi premium',
'Premium_Theme_Fallback_Text' => 'Per ora il Suo negozio mostra il tema Electronics standard. Le Sue impostazioni premium qui sotto vengono conservate e tornano attive non appena il Suo piano include di nuovo i Temi premium per il negozio.',
'Electronics_Premium_Theme_Hint' => 'Un negozio di elettronica premium, chiaro per impostazione predefinita con un interruttore per la modalità scura per i visitatori: mega menu, offerte del giorno con conto alla rovescia in tempo reale, filtri per specifiche, confronto prodotti, bundle e visti di recente. Slide hero e riquadri vuoti mostrano invece i Suoi prodotti.',
